// ODRL-AP-NL viewer — edit- & generatiemodule (ESM, DOM-vrij, node-testbaar).
//
// Verantwoordelijkheden (laag 1 + laag 3 uit notes/analyse-schema-gedreven-editors.md):
//   1. Structuurbewerkingen op de drietraps: Offer/Agreement/Permission/Duty
//      toevoegen, dupliceren, verwijderen; velden (literals/IRI's) zetten.
//   2. Skelet-generatie: leeg drietraps-skelet (Offer + Agreement + Permission)
//      met verplichte basiselementen en profieldeclaratie voorgevuld.
//   3. Raw-RDF-vangnet: een subject-sluiting (zoals het bronpaneel toont) als
//      Turtle terug de graaf in mergen, round-trip-veilig.
//   4. Export van de volledige graaf als Turtle en JSON-LD.
//   5. termOptions: dropdown-vulling uit de geladen graaf (bekende odrl/apnl-
//      termen + alles met rdfs:label).
//
// Alle functies muteren de meegegeven N3.Store — in de praktijk de
// schrijf-facade van bewerkstore.js, die de delta's aan de bron-sync meldt.
// Wat er ná een mutatie gebeurt (het model herbouwen, de weergave bijwerken,
// undo/redo, het wegschrijven naar bron of endpoint) is aan de bewerk-stand in
// doc.js: voerUit() en herrenderNaMutatie(). De losse drie-panelen-editor
// (app.js) waar deze module ooit voor gebouwd is, bestaat niet meer.

import * as N3 from 'n3';
import {
  PREFIXES, allPrefixes, prefixNamespace, curie, labelFor, prunePrefixes,
  subjectJsonLdBody, jsonLdContext, targetPredicates, PROFILE_PATTERNS,
  dedupeTriples, vrijeBlank, localName,
} from './parse.js';
import { langRank } from './i18n.js';
import { termSleutel, termVan } from './term.js';

const { DataFactory, Parser, Store } = N3;
// GEEN `blankNode` hier: de bewerklaag mint blanke knopen uitsluitend via
// `mintBlank` hieronder. De naamloze fabriek weglaten uit dit bestand is de
// goedkoopste bewaking tegen een terugval.
const { namedNode, literal } = DataFactory;

const RDF = PREFIXES.rdf;
const RDFS = PREFIXES.rdfs;
const ODRL = PREFIXES.odrl;
const APNL = PREFIXES.apnl;
const DCT = PREFIXES.dct;
const DCAT = PREFIXES.dcat;
const XSD = PREFIXES.xsd;
const FOAF = PREFIXES.foaf;
const DPV = PREFIXES.dpv;

// Default-profieldeclaratie voor nieuw gegenereerd beleid (B14): de editor is
// bewust een AP-NL-editor en stempelt skeletten met dit profiel. Wie de
// editor voor een ander profiel inzet, past alléén deze constante aan (of
// leidt hem t.z.t. af uit de geladen profiel-ontologie).
export const DEFAULT_PROFILE = APNL + 'profiel';

/** EEN SUBJECT UIT WELKE VORM DAN OOK — de decoder van `model/term.js`, met
 *  één tak erbij.
 *
 *  De normalisatie zelf staat sinds de consolidatie één keer, in de leaf
 *  `model/term.js` (elf decodeerplekken over acht bestanden zijn daarop
 *  samengebracht; de reden waarom die leaf niet HIER kon wonen staat in zijn
 *  kop: `edit.js` ligt achter de lazy-grens en twee decodeerplekken liggen in
 *  de instap).
 *
 *  DE EXTRA TAK IS "GEEF TERUG WAT JE KREEG". `termVan` levert `null` voor
 *  alles wat geen knoop is; de mutaties hieronder geven hun invoer liever
 *  ongewijzigd door aan N3, zodat een onbekende vorm daar luid stukloopt in
 *  plaats van hier stil in een `null` te verdwijnen. */
const nn = (x) => termVan(x) ?? x;

function objsOf(store, s, p) {
  return store.getQuads(s, namedNode(p), null, null).map((q) => q.object);
}
function objOf(store, s, p) {
  const o = objsOf(store, s, p);
  return o.length ? o[0] : null;
}

// --- Sluitingen -------------------------------------------------------------

// Alle quads van `start` plus de transitieve sluiting over blank nodes
// (zelfde wandeling als subjectTurtle in parse.js).
export function closureQuads(store, start) {
  const collected = [];
  const seen = new Set();
  const stack = [nn(start)];
  while (stack.length) {
    const s = stack.pop();
    const key = s.termType + ':' + s.value;
    if (seen.has(key)) continue;
    seen.add(key);
    for (const q of store.getQuads(s, null, null, null)) {
      collected.push(q);
      if (q.object.termType === 'BlankNode') stack.push(q.object);
    }
  }
  return collected;
}

// --- IRI-hulpjes ------------------------------------------------------------

// Expandeer gebruikersinvoer: "odrl:read" -> volle IRI via bekende prefixes;
// volle IRI's/urn's blijven ongemoeid.
export function expandIri(text) {
  if (typeof text !== 'string') return text;
  const t = text.trim();
  if (!t) return '';
  if (/^https?:\/\//.test(t) || t.startsWith('urn:')) return t;
  const m = t.match(/^([\w-]+):(.*)$/);
  if (m) {
    const ns = prefixNamespace(m[1]); // statisch én brongedreven (bv. brp:)
    if (ns) return ns + m[2];
  }
  return t;
}

/** WAT MAG ER ALS IRI DE GRAAF IN? Dezelfde IRIREF-tekenvalidatie als verken.js
 *  (validIri) en sparql.js (iriRef): een ABSOLUTE IRI (dus met een schema)
 *  zonder de tekens die de <…>-vorm breken. Dit is geen stijlregel maar een
 *  gegevensbescherming: een half getypt label als "Gemeente Vlierdam" komt door
 *  `expandIri` ongemoeid heen, wordt als <Gemeente Vlierdam> weggeschreven, en
 *  dan is de TTL-bron bij de volgende lading niet meer te parsen — de autosave
 *  heeft hem dan al op schijf gezet.
 *
 *  Een curie met een ONBEKEND prefix (`foo:bar`) blijft toegestaan: dat is
 *  syntactisch een geldige IRI en hij round-trip't door de serialisatie heen.
 *
 *  HIJ WOONDE IN `model/velden.js` (de veldlaag) en is bij het hernoemen van
 *  knopen hierheen verhuisd, naast zijn twee broers `expandIri` en `mintIri`.
 *  Reden: `hernoemKnoop` hieronder schrijft een IRI als SUBJECT, en die
 *  bewerking moet zelf kunnen weigeren — een ongeldige subject-IRI maakt de bron
 *  onleesbaar, en dan is "de UI toetst het wel" een belofte van de verkeerde
 *  laag. `velden.js` exporteert hem door, net als `zetLiteral`, dus elke
 *  bestaande aanroeper (kaartveld, sloteditor, de veldtests) blijft ongewijzigd. */
export function geldigeIriTekst(s) {
  const v = String(s || '');
  if (!/^[A-Za-z][A-Za-z0-9+.-]*:/.test(v)) return false;
  return !/[\s<>"{}|\\^`]/.test(v);
}

// Vind een nog niet gebruikte IRI op basis van baseIri (suffix -2, -3, ...).
export function mintIri(store, baseIri) {
  let iri = baseIri;
  let i = 2;
  while (store.getQuads(namedNode(iri), null, null, null).length
      || store.getQuads(null, null, namedNode(iri), null).length) {
    iri = baseIri + '-' + i++;
  }
  return iri;
}

/** De blanke tegenhanger van `mintIri`: een VERSE blanke knoop.
 *
 *  Elke plek in dit bestand die een nieuwe blanke knoop nodig heeft, gebruikt
 *  deze — nooit de naamloze `blankNode()`. Waarom dat moet, staat bij
 *  `vrijeBlank` in parse.js: de naamloze fabriek deelt haar teller met de
 *  parser, en die teller staat in de worker en op de hoofddraad onafhankelijk
 *  op nul, zodat een mutatie op de hoofddraad zo een bestaande `[ … ]`-knoop
 *  "opnieuw" mint en haar triples erft.
 *
 *  Eén teller voor de hele bewerklaag: hij loopt monotoon door, dus twee mints
 *  binnen één aanroep (zie `addDuty`) kunnen ook niet samenvallen voordat de
 *  eerste in de graaf staat. Het prefix `edit-` botst per constructie niet met
 *  wat de parser produceert: die mint anonieme knopen als `n3-<n>` en labels
 *  uit het document als `b<n>_<label>`. */
const BEWERK_TELLER = { n: 0 };
function mintBlank(store) {
  return vrijeBlank(store, 'edit-', BEWERK_TELLER);
}

function today() {
  return new Date().toISOString().slice(0, 10);
}

// --- Veldbewerkingen --------------------------------------------------------

export function removeProp(store, subject, predIri) {
  store.removeQuads(store.getQuads(nn(subject), namedNode(predIri), null, null));
}

// Vervang alle waarden van (subject, pred) door één literal; lege waarde = weg.
export function setLiteral(store, subject, predIri, value, opts = {}) {
  removeProp(store, subject, predIri);
  if (value == null || value === '') return;
  const lit = opts.datatype ? literal(String(value), namedNode(opts.datatype))
    : (opts.lang ? literal(String(value), opts.lang) : literal(String(value)));
  store.addQuad(nn(subject), namedNode(predIri), lit);
}

// OPSLAAN VAN ÉÉN GETOONDE TEKSTWAARDE. Drie gevallen, en het middelste is de
// reden dat deze functie naast `setLiteral` bestaat:
//
//  1. LEEGMAKEN (waarde ''): alle waarden weg, óók de anderstalige. Bewuste
//     keuze — een leeg veld betekent "deze knoop heeft deze eigenschap niet",
//     en een titel die in het Nederlands verdwijnt maar in het Engels blijft
//     staan is geen begrijpelijke uitkomst van "veld leegmaken";
//  2. MEER DAN ÉÉN LITERAL op hetzelfde predicaat: de weergave toont er ÉÉN
//     (die het best bij de voorkeurstaal past), en een bewerking hoort precies
//     die te vervangen — in haar eigen taal- of datatypevorm. Een kale
//     `setLiteral` zou de vertaling zonder waarschuwing opruimen omdat zij
//     toevallig niet op het scherm stond;
//  3. ÉÉN (of geen) literal: de gewone weg, met de VORM van wat er stond, en
//     `standaard` als er nog niets was.
//
// DE HANDTEKENING, want zij is zes argumenten lang en dat is een keuze.
//
//   zetLiteral(store, lees, subject, predIri, value, standaard = {})
//
// `store` is de SCHRIJF-facade (bewerkstore); `lees` is de graaf waaruit de
// bestaande waarden worden opgehaald. Ze staan apart omdat de facade
// schrijfacties naar de graph van de bewerkbron routeert en dus niet
// vanzelfsprekend de plek is om de bestaande vorm uit te lezen. Wie een facade
// heeft die WEL ongefilterd doorleest — dat doet `bewerkStore` — geeft hem
// gewoon twee keer mee (`zetLiteral(f, f, …)`); dat is de vorm die de
// kaartvelden gebruiken. `lees` mag ook `null` zijn: dan is er niets bestaands
// en gelden `standaard` en de kale weg.
//
// DEZE FUNCTIE BESTOND TWEE KEER (review I-5 / formulieren-I-1). `model/velden.js`
// droeg een tweede kopie met een andere handtekening
// (`zetLiteral(f, termOrIri, predIri, waarde, standaard)`) en een eigen paar
// `getoondeLiteral`/`literalVorm` ernaast. Twee lanes hadden hem onafhankelijk
// uit dezelfde bron gebouwd; de drift landde STIL, want de kopieën stonden in
// verschillende bestanden en gaven dus geen merge-conflict — en omdat de
// argumentvolgorde verschilt, faalt de verkeerde import niet luid. Deze vorm is
// de canonieke: hij woont in de modellaag naast `setLiteral`, waar hij
// hoort. Wat er uit de andere kopie is meegekomen, staat hieronder met een
// eigen reden; niets is er onderweg verdwenen.
//
// Gedragsbron: `zetLiteral`, `getoondeLiteral` en `literalVorm` in de bevroren
// viewer (viewer-bevroren/assets/doc.js r.1736-1794). Zij stonden daar in de weergave
// omdat doc.js één bestand was; de keuze "welke literal toont de weergave"
// leunt uitsluitend op `langRank` uit i18n.js en hoort dus hier — één plek voor
// beide lanes die haar in golf B nodig hebben (formulierrijen en kaartvelden).
export function zetLiteral(store, lees, subject, predIri, value, standaard = {}) {
  const nieuw = value == null ? '' : String(value);
  if (!nieuw) { setLiteral(store, subject, predIri, ''); return; }
  const literals = (lees ? lees.getQuads(nn(subject), namedNode(predIri), null, null) : [])
    .filter((q) => q.object.termType === 'Literal');
  if (literals.length > 1) {
    const doel = getoondeLiteral(literals);
    const vorm = literalVorm(doel.object) || {};
    store.removeQuads([doel]);
    // DE VERVANGING BLIJFT IN DE GRAPH DIE DE LITERAL BEZAT — meegekomen uit de
    // kopie in `velden.js`, en het is de juiste kant. De @nl en de @en van één
    // knoop horen in hetzelfde bestand te blijven staan; zonder deze graph zou
    // de facade de vervanging naar de werkgraph routeren en de vertaling stil
    // uit haar eigen bron tillen. `bewerkStore` laat een quad die zelf een
    // graph meebrengt met opzet staan — dit is precies de aanroep waarvoor die
    // uitzondering bestaat.
    store.addQuad(doel.subject, doel.predicate,
      // eslint-disable-next-line no-nested-ternary
      (vorm.lang ? literal(nieuw, vorm.lang)
        : (vorm.datatype ? literal(nieuw, namedNode(vorm.datatype)) : literal(nieuw))),
      doel.graph);
    return;
  }
  setLiteral(store, subject, predIri, nieuw,
    literalVorm(literals[0] && literals[0].object) || standaard);
}

/** De literal die de weergave TOONT: die het best bij de voorkeurstaal past —
 *  dezelfde keuze als `pickLabel`. Zonder deze stap vervangt een bewerking de
 *  eerste-de-beste uit de graaf en verspringt het scherm naar een andere taal. */
export function getoondeLiteral(literalQuads) {
  let best = null;
  let bestRang = Infinity;
  for (const q of literalQuads) {
    const r = langRank(q.object.language || '');
    if (r < bestRang) { bestRang = r; best = q; }
  }
  return best;
}

/** De literal-vorm van een bestaande waarde overnemen: taalmarkering wint,
 *  anders een echt datatype (xsd:date), anders kaal. */
export function literalVorm(o) {
  if (!o || o.termType !== 'Literal') return null;
  if (o.language) return { lang: o.language };
  if (o.datatype && !/#string$/.test(o.datatype.value)) return { datatype: o.datatype.value };
  return {};
}

// Vervang alle waarden van (subject, pred) door één IRI; lege waarde = weg.
export function setIri(store, subject, predIri, iri) {
  removeProp(store, subject, predIri);
  const full = expandIri(iri);
  if (!full) return;
  store.addQuad(nn(subject), namedNode(predIri), namedNode(full));
}

// --- Constraint-/refinement-bewerkingen -------------------------------------

// Zet de drie delen van een constraint. right: {value, kind:'iri'|'literal',
// lang?, datatype?}. Laat odrl:rightOperandReference met rust.
export function setConstraint(store, cTerm, { left, operator, right } = {}) {
  if (left !== undefined) setIri(store, cTerm, ODRL + 'leftOperand', left);
  if (operator !== undefined) setIri(store, cTerm, ODRL + 'operator', operator);
  if (right !== undefined) {
    removeProp(store, cTerm, ODRL + 'rightOperand');
    if (right && right.value !== '' && right.value != null) {
      if (right.kind === 'iri') {
        store.addQuad(nn(cTerm), namedNode(ODRL + 'rightOperand'), namedNode(expandIri(right.value)));
      } else {
        const lit = right.datatype ? literal(String(right.value), namedNode(right.datatype))
          : (right.lang ? literal(String(right.value), right.lang) : literal(String(right.value)));
        store.addQuad(nn(cTerm), namedNode(ODRL + 'rightOperand'), lit);
      }
    }
  }
}

// NIEUWE, LEGE CONSTRAINT (of refinement) aan een rule hangen.
//
// EEN TOEGEVOEGDE VOORWAARDE DRAAGT GEEN GEFINGEERDE SEMANTIEK
// (eigenaarsbesluit 8 sep 2026, letterlijk: "tijdstip is kleiner dan of gelijk
// aan '2026-09-08' als default voorwaarde slaat nergens op"). Tot deze ronde
// schreef deze functie odrl:dateTime / odrl:lteq / vandaag, met als motivering
// dat "het formulier iets moet hebben om te tonen". Dat is een reden van de
// WEERGAVE, betaald met een uitspraak in de DATA: wie de rij liet staan hield
// een tijdgrens in zijn beleid die niemand gevraagd had, en wie hem las kon niet
// zien dat hij verzonnen was.
//
// Wat de knoop nu wél draagt is zijn TYPE. Dat is geen betekenis maar structuur:
// `odrl:Constraint` zegt alleen dát dit een voorwaarde is — precies wat de
// aanroeper zojuist heeft gevraagd — en de weergave leest er haar drie
// (ontbrekende) slots uit, met de "ontbreekt"-chips die zij voor elk onvolledig
// slot toont. De UI opent de sloteditor meteen op zo'n verse voorwaarde
// (`VoorwaardeStrook`, ui/bewerk/integratie/rij-bewerk.tsx), dus de lezer ziet
// niet een raadsel maar een formulier met de cursor in de grootheid.
//
// `opts` vult alleen dát voor wat de aanroeper ECHT weet:
//   - `left`/`operator` — de groeperingsvoorwaarde-shortcut kent de grootheid
//     van het dimensievakje (odrl:purpose) en verder niets;
//   - `opActie` — hang de voorwaarde als refinement aan de ACTIE-knoop in plaats
//     van aan de regel. Dat is waar ODRL-AP-NL zijn refinements zet
//     (`[ rdf:value <actie> ; odrl:refinement … ]`, zie `setPurpose`); zonder
//     deze schakelaar zou een refinement rechtstreeks onder de regel belanden en
//     door `readAction` nooit gelezen worden.
export function addConstraint(store, ruleTerm, predIri = ODRL + 'constraint', opts = {}) {
  const c = mintBlank(store);
  store.addQuad(c, namedNode(RDF + 'type'), namedNode(ODRL + 'Constraint'));
  const links = opts.left ? expandIri(opts.left) : '';
  if (links) store.addQuad(c, namedNode(ODRL + 'leftOperand'), namedNode(links));
  const op = opts.operator ? expandIri(opts.operator) : '';
  if (op) store.addQuad(c, namedNode(ODRL + 'operator'), namedNode(op));
  const houder = opts.opActie ? ensureActionNode(store, ruleTerm) : nn(ruleTerm);
  store.addQuad(houder, namedNode(predIri), c);
  return c;
}

// Vind (of maak) de action-node van een permission en geef die terug als node
// waaraan refinements gehangen kunnen worden (rdf:value-vorm).
//
// EEN VERSE ACTIE-KNOOP DRAAGT GEEN ACTIE (eigenaarsbevinding 9 sep 2026, punt 1
// tweeling). Tot deze ronde stempelde deze functie `rdf:value odrl:read` op de
// knoop die zij maakte, en dat is precies dezelfde gefingeerde semantiek als de
// actie-prefill in `addRule`: wie een REFINEMENT aan een actieloze regel hangt —
// de 1c-snelkoppeling doet dat — kreeg er ongevraagd "raadplegen" bij, in de
// data, zonder dat iets op het scherm zei dat het verzonnen was.
//
// Het eerlijke antwoord is een actie-knoop ZONDER rdf:value: `[ odrl:refinement
// … ]`. Dat is een vorm die de leeskant aankan — `readAction` (parse.js r.1454)
// geeft dan `{ value: null, refinements, nodeTerm }` terug, en de Actie-rij toont
// haar lege veld. Zodra de lezer de actie kiest, schrijft `setAction` hem als
// rdf:value ín deze knoop (zie daar), dus de refinements blijven staan.
function ensureActionNode(store, permTerm) {
  const p = nn(permTerm);
  let action = objOf(store, p, ODRL + 'action');
  if (!action) {
    action = mintBlank(store);
    store.addQuad(p, namedNode(ODRL + 'action'), action);
    return action;
  }
  const hasValue = objOf(store, action, RDF + 'value');
  const ownQuads = store.getQuads(action, null, null, null).length;
  if (action.termType === 'NamedNode' && !hasValue && ownQuads === 0) {
    // Directe actie-IRI: herstructureer naar [ rdf:value <actie> ] zodat er
    // een refinement aan kan.
    store.removeQuads(store.getQuads(p, namedNode(ODRL + 'action'), action, null));
    const node = mintBlank(store);
    store.addQuad(node, namedNode(RDF + 'value'), action);
    store.addQuad(p, namedNode(ODRL + 'action'), node);
    return node;
  }
  return action;
}

// Zet (of verwijder) de doelbindings-refinement (odrl:purpose) van een permission.
export function setPurpose(store, permTerm, { purpose, operator = ODRL + 'eq' } = {}) {
  const p = nn(permTerm);
  const action = objOf(store, p, ODRL + 'action');
  // Bestaande purpose-refinement zoeken.
  let existing = null;
  if (action) {
    for (const r of objsOf(store, action, ODRL + 'refinement')) {
      const left = objOf(store, r, ODRL + 'leftOperand');
      if (left && left.value === ODRL + 'purpose') { existing = r; break; }
    }
  }
  const full = expandIri(purpose);
  if (!full) {
    if (existing && action) {
      store.removeQuads(store.getQuads(action, namedNode(ODRL + 'refinement'), existing, null));
      if (existing.termType === 'BlankNode') store.removeQuads(closureQuads(store, existing));
    }
    return null;
  }
  const actionNode = ensureActionNode(store, p);
  let c = existing;
  if (!c) {
    c = mintBlank(store);
    store.addQuad(c, namedNode(RDF + 'type'), namedNode(ODRL + 'Constraint'));
    store.addQuad(c, namedNode(ODRL + 'leftOperand'), namedNode(ODRL + 'purpose'));
    store.addQuad(actionNode, namedNode(ODRL + 'refinement'), c);
  }
  setIri(store, c, ODRL + 'operator', operator);
  setIri(store, c, ODRL + 'rightOperand', full);
  return c;
}

// Zet de actie van een permission (behoudt een eventuele rdf:value-structuur
// met refinements).
//
// DE BLANKE ACTIE-KNOOP TELT MEE, óók zonder rdf:value. Sinds `ensureActionNode`
// geen actie meer fabriceert, bestaat de vorm `[ odrl:refinement … ]` zonder
// rdf:value echt: dat is een verse regel waaraan de 1c-snelkoppeling een
// doelbinding hing. De oude toets keek alleen naar een BESTAANDE rdf:value en
// viel voor die knoop terug op de else-tak — die de hele odrl:action vervangt
// door een kale IRI en dus de zojuist ingevulde doelbinding weggooit. Een blanke
// knoop is per constructie de wikkel-vorm; daar hoort de actie ín.
export function setAction(store, permTerm, actionIri) {
  const p = nn(permTerm);
  const full = expandIri(actionIri);
  if (!full) return;
  const action = objOf(store, p, ODRL + 'action');
  if (action && (action.termType === 'BlankNode' || objOf(store, action, RDF + 'value'))) {
    removeProp(store, action, RDF + 'value');
    store.addQuad(action, namedNode(RDF + 'value'), namedNode(full));
  } else {
    removeProp(store, p, ODRL + 'action');
    store.addQuad(p, namedNode(ODRL + 'action'), namedNode(full));
  }
}

// --- Targets ----------------------------------------------------------------

// Target-predicaten uitsluitend data-gedreven (C4): odrl:target plus alles
// wat de geladen graaf als rdfs:subPropertyOf odrl:target declareert —
// dezelfde afleiding als parse.js (bv. brp:verzochteRubriek uit het
// registerfragment examples/labels-brp.ttl).
const targetPreds = targetPredicates;

export function addTarget(store, permTerm, iri) {
  const full = expandIri(iri);
  if (!full) return;
  store.addQuad(nn(permTerm), namedNode(ODRL + 'target'), namedNode(full));
}

export function removeTarget(store, permTerm, iri) {
  const full = expandIri(iri);
  for (const pred of targetPreds(store)) {
    store.removeQuads(store.getQuads(nn(permTerm), namedNode(pred), namedNode(full), null));
  }
}

// --- Structuurbewerkingen ---------------------------------------------------

// Nieuwe REGEL aan een policy hangen. ODRL zet odrl:Permission en
// odrl:Prohibition als twee subklassen van odrl:Rule naast elkaar: dezelfde
// vorm, een ander type en een ander koppelpredicaat. Eén functie dus, met de
// soort als parameter — twee losse kopieën zouden onvermijdelijk uit elkaar
// gaan lopen zodra de vorm van een verse regel verandert.
//
// EEN VERSE REGEL DRAAGT ALLEEN WAT DE AANROEPER WEET (eigenaarsbevinding 9 sep
// 2026, punten 1 en 2). Er stonden hier twee voorvullingen, en allebei waren ze
// een uitspraak in de DATA die niemand had gedaan:
//
//   - `odrl:read` als ACTIE. Eigenaar, letterlijk: "Hij kiest zelf raadplegen
//     als actie bij nieuwe toestemming." Een verse regel heeft nu geen
//     odrl:action; de Actie-rij toont haar lege veld (zie `actieRij` in
//     ui/kaart/regels.tsx) en de toevoegfocus loopt van de titel door naar dat
//     veld;
//   - een GEMINTE DOEL-IRI met het label "(vul doel in)" als er geen
//     `purposeIri` was. Die tak was na de fixronde van 8 sep door geen enkele
//     aanroeper meer gevraagd — `addAgreement`, `createSkeleton` en de drie
//     kaart-ghosts gaven allemaal `withPurpose: false` mee — en stond dus alleen
//     nog als valstrik klaar voor de volgende aanroeper. Weg, met de optie
//     `withPurpose` erbij: een schakelaar met nog maar één stand is geen keuze.
//
// WAT BLIJFT is de voorvulling die de aanroeper ECHT weet: `purposeIri` (de
// ghost binnen een dimensievakje kent de waarde van dat vakje) en `targetIri`
// (het skelet neemt de gegevensbron van het aanbod over). Dat is geen verzinsel
// maar een gegeven van de plek waar geklikt werd.
function addRule(store, policyTerm, { klasse, pred }, opts = {}) {
  const p = mintBlank(store);
  store.addQuad(p, namedNode(RDF + 'type'), namedNode(ODRL + klasse));
  store.addQuad(nn(policyTerm), namedNode(ODRL + pred), p);
  if (opts.purposeIri) setPurpose(store, p, { purpose: opts.purposeIri, operator: ODRL + 'eq' });
  if (opts.targetIri) addTarget(store, p, opts.targetIri);
  return p;
}

// --- Een BESTAANDE benoemde regel hergebruiken ------------------------------
//
// EIGENAARSAANVULLING 9 SEP 2026, LETTERLIJK: "En ook voor rules; hoe je
// bestaande named rules kan hergebruiken i.p.v. opnieuw aanmaken".
//
// WAT ER ONTBRAK. Elke toevoegroute hierboven MINT: `addPermission`,
// `addProhibition` en `addDuty` maken een verse blanke knoop en hangen hem op.
// Een stelselplicht die in vijf beleidssets hoort, of een toestemming die twee
// aanbieders letterlijk delen, was daarmee vijf keer overtypen — en vijf knopen
// die de volgende bewerking vijf keer moet bijwerken.
//
// EEN KOPPELING IS ÉÉN TRIPLE, en dat is de hele mutatie: `policy →
// odrl:permission/prohibition/obligation → <bestaande IRI>`. De regel zelf wordt
// niet aangeraakt en al helemaal niet gekopieerd — hij is GEDEELD, en de
// leeskant zegt dat ook: `GedeeldMarker` (ui/bewerk/slepen/gedeeld.tsx) telt de
// kaarten waarin een knoop leeft en licht de andere op zodra je erheen wijst.
//
// ALLEEN BENOEMDE REGELS. Een blanke knoop hoort bij precies één ouder en is
// buiten dit document niet aanwijsbaar; een tweede beleid dat ernaar wijst
// serialiseert niet naar een tweede bron. Wie een blanke regel toch wil delen,
// geeft hem eerst een naam — `benoemKnoop` verderop is die route.
//
// ONTKOPPELEN heeft geen eigen mutatie nodig: het ✕ op de rij loopt over
// `losmaakQuads`/`removeAttached`, en die wissen alléén de koppeling zolang de
// knoop elders in gebruik blijft (`blijftInGebruik` in
// ui/bewerk/integratie/anker.ts). Dat onderscheid maakt de wisroute dus al.

/** DE KLASSE DIE BIJ EEN KOPPELPREDICAAT HOORT. `odrl:duty` en
 *  `odrl:consequence` hangen dezelfde soort knoop op als `odrl:obligation` —
 *  een `odrl:Duty` — alleen op een andere plek. */
const KOPPEL_KLASSE = {
  [ODRL + 'permission']: ODRL + 'Permission',
  [ODRL + 'prohibition']: ODRL + 'Prohibition',
  [ODRL + 'obligation']: ODRL + 'Duty',
  [ODRL + 'duty']: ODRL + 'Duty',
  [ODRL + 'consequence']: ODRL + 'Duty',
};

/** De sleutel waaronder de UI een regelsoort kent (`ctx.soorten` van de
 *  kaart-ghost), per klasse. */
const SOORT_VAN_KLASSE = {
  [ODRL + 'Permission']: 'toestemming',
  [ODRL + 'Prohibition']: 'verbod',
  [ODRL + 'Duty']: 'duty',
};

/** WELKE SOORT REGEL IS DEZE KNOOP? Het `rdf:type` wint — dat is wat de bron
 *  ZEGT. Draagt de knoop er geen (dat mag: ODRL leidt de soort ook uit het
 *  koppelpredicaat af), dan telt de plek waar hij hangt. Levert dat niets op,
 *  dan is dit geen regel en hoort hij nergens in de keuzelijst. */
function regelKlasse(store, term) {
  const t = nn(term);
  for (const ty of objsOf(store, t, RDF + 'type')) {
    if (SOORT_VAN_KLASSE[ty.value]) return ty.value;
  }
  for (const q of store.getQuads(null, null, t, null)) {
    const k = KOPPEL_KLASSE[q.predicate.value];
    if (k) return k;
  }
  return '';
}

/** DE BENOEMDE REGELS UIT ÁLLE GELADEN BRONNEN, per soort, met hun label en hun
 *  HERKOMST — de titels van de beleidsstukken waar ze nu aan hangen.
 *
 *  Die herkomst is geen versiering: twee regels heten in dit domein makkelijk
 *  allebei "Raadplegen", en dan is "uit welk beleid komt hij" het enige verschil
 *  dat de lezer ziet vóórdat hij kiest. Zij staat als lijst en niet als tekst —
 *  de UI voegt hem samen in de taal waarin zij op dat moment staat.
 *
 *  Gesorteerd op label, met dezelfde `localeCompare`-collatie als `termOptions`:
 *  wie een lijst afkapt op N treffers, kapt hem dan alfabetisch af. */
export function regelOpties(store) {
  const per = { toestemming: new Map(), verbod: new Map(), duty: new Map() };
  const kandidaten = new Map();
  for (const pred of AANHECHT_PREDS) {
    for (const q of store.getQuads(null, namedNode(pred), null, null)) {
      if (q.object.termType === 'NamedNode') kandidaten.set(q.object.value, q.object);
    }
  }
  for (const klasse of Object.keys(SOORT_VAN_KLASSE)) {
    for (const q of store.getQuads(null, namedNode(RDF + 'type'), namedNode(klasse), null)) {
      if (q.subject.termType === 'NamedNode') kandidaten.set(q.subject.value, q.subject);
    }
  }
  for (const [iri, t] of kandidaten) {
    const soort = SOORT_VAN_KLASSE[regelKlasse(store, t)];
    if (!soort || per[soort].has(iri)) continue;
    const herkomst = [];
    for (const q of store.getQuads(null, null, t, null)) {
      if (!KOPPEL_KLASSE[q.predicate.value]) continue;
      const naam = labelFor(store, q.subject);
      if (naam && !herkomst.includes(naam)) herkomst.push(naam);
    }
    per[soort].set(iri, { iri, curie: curie(iri), label: labelFor(store, t), herkomst });
  }
  const sort = (m) => [...m.values()].sort((a, b) => a.label.localeCompare(b.label, 'nl'));
  return { toestemming: sort(per.toestemming), verbod: sort(per.verbod), duty: sort(per.duty) };
}

/** MAG DEZE KOPPELING? `{ ok: true }` of `{ ok: false, reden }` met
 *  `ongeldig` (geen bruikbare IRI-tekst), `onbekend` (die knoop staat niet in de
 *  graaf — koppelen zou een dode verwijzing leggen), `verkeerdeSoort` (een verbod
 *  onder `odrl:permission` maakt van een verbod stil een toestemming) of
 *  `alGekoppeld` (de triple staat er al; een tweede zou niets doen en wél een
 *  ↶-stap kosten).
 *
 *  Op de LEESgraaf te stellen, om dezelfde reden als `hernoemToets`. */
export function koppelToets(store, policyTerm, predIri, regelIri) {
  const iri = expandIri(String(regelIri || '').trim());
  if (!iri || !geldigeIriTekst(iri)) return { ok: false, reden: 'ongeldig' };
  const r = namedNode(iri);
  if (!store.getQuads(r, null, null, null).length
      && !store.getQuads(null, null, r, null).length) {
    return { ok: false, reden: 'onbekend' };
  }
  const p = nn(policyTerm);
  if (!p) return { ok: false, reden: 'onbekend' };
  if (store.getQuads(p, namedNode(predIri), r, null).length) {
    return { ok: false, reden: 'alGekoppeld' };
  }
  const verwacht = KOPPEL_KLASSE[predIri];
  const klasse = regelKlasse(store, r);
  if (!klasse || (verwacht && klasse !== verwacht)) return { ok: false, reden: 'verkeerdeSoort' };
  return { ok: true };
}

/** DE KOPPELING ZELF: één triple erbij, en verder niets. `{ ok: true }` of het
 *  oordeel van `koppelToets`. Eén undo-stap is de zorg van de aanroeper
 *  (`voerUit(..., { groep: true })`), net als bij elke andere structuurmutatie. */
export function koppelRegel(store, policyTerm, predIri, regelIri) {
  const oordeel = koppelToets(store, policyTerm, predIri, regelIri);
  if (!oordeel.ok) return oordeel;
  const r = namedNode(expandIri(String(regelIri).trim()));
  store.addQuad(nn(policyTerm), namedNode(predIri), r);
  return { ok: true, term: r };
}

// --- Een BESTAANDE benoemde VOORWAARDE hergebruiken --------------------------
//
// EIGENAARSFEEDBACK 11 SEP 2026, LETTERLIJK: "Ik zie nog niet hoe ik nodes kan
// hergebruiken. Voorwaarden toevoegen is nog steeds alleen invoeren van de
// left/rightOperand etc. bijv."
//
// Dit is de regel-familie hierboven, één laag dieper. Twee dingen zijn anders,
// en allebei omdat een voorwaarde geen regel is:
//
//  1. DE PLEK BEPAALT HET PREDICAAT, en niet de SOORT van de knoop. Bij een
//     regel leidt `KOPPEL_KLASSE` uit `odrl:permission` af dat er een
//     `odrl:Permission` hoort — een verbod onder dat predicaat zou stil van
//     soort veranderen. Een voorwaarde kent dat onderscheid niet: dezelfde
//     knoop is een `odrl:constraint` van een regel (een voorwaarde aan het
//     GEBRUIK) óf een `odrl:refinement` van een actie-knoop of een collectie
//     (een AFBAKENING), en welk van de twee het is, is een eigenschap van de
//     PLEK. De aanroeper geeft hem dus mee, precies zoals `addConstraint` hem
//     al aanneemt; de toets controleert alleen dát het een van die twee is.
//  2. LOGISCHE VOORWAARDEN TELLEN MEE. Gemeten vóór de bouw en vastgelegd in
//     `model/test/voorwaardehergebruik.test.mjs` (de twee MEETSTAP-gevallen):
//     `readConstraints` in parse.js leest een BENOEMDE `odrl:LogicalConstraint`
//     volledig — zij krijgt haar samengestelde zin ("… óf …") en haar
//     `logical`-merk in élke regel waar zij aan hangt. Wat de leeskant aankan,
//     hoort de keuzelijst te bieden.
//
// ONTKOPPELEN heeft ook hier geen eigen mutatie nodig: het ✕ van een
// voorwaarderij loopt over dezelfde `losmaakQuads`/`blijftInGebruik` als een
// regelrij (ui/bewerk/integratie/anker.ts), en die wissen bij een knoop die
// elders in gebruik blijft alléén de koppeling.

/** DE TWEE PLEKKEN waar een voorwaarde kan hangen. Dezelfde twee die
 *  `PROFILE_PATTERNS.constraintPreds` in parse.js als voorwaardepositie leest —
 *  de keuzelijst mag niets aanbieden dat de leeskant daarna niet als voorwaarde
 *  terugvindt. */
const VOORWAARDE_PREDS = [ODRL + 'constraint', ODRL + 'refinement'];

/** DE KLASSEN DIE ALS VOORWAARDE TELLEN, gelijk aan
 *  `PROFILE_PATTERNS.constraintClasses`. */
const VOORWAARDE_KLASSEN = [ODRL + 'Constraint', ODRL + 'LogicalConstraint'];

/** IS DEZE KNOOP EEN VOORWAARDE? Zelfde tweetrapsredenering als `regelKlasse`
 *  hierboven: het `rdf:type` wint — dat is wat de bron ZEGT — en draagt de knoop
 *  er geen (dat mag; ODRL leidt het ook uit de plek af), dan telt de plek waar
 *  hij hangt. Zo telt een profielsubklasse die in constraint-positie hangt
 *  vanzelf mee, zonder dat deze module de subklassenhiërarchie hoeft te
 *  herbouwen die parse.js al kent. */
function isVoorwaarde(store, term) {
  const t = nn(term);
  if (!t) return false;
  for (const ty of objsOf(store, t, RDF + 'type')) {
    if (VOORWAARDE_KLASSEN.includes(ty.value)) return true;
  }
  for (const q of store.getQuads(null, null, t, null)) {
    if (VOORWAARDE_PREDS.includes(q.predicate.value)) return true;
  }
  return false;
}

/** DE AANHECHTINGEN WAARLANGS EEN HOUDER AAN ZIJN BELEIDSSTUK HANGT.
 *  `odrl:action` staat erbij omdat een refinement niet aan de regel hangt maar
 *  aan haar (meestal blanke) actie-knoop — zonder die schakel zou de herkomst
 *  van elke doelbinding "naamloos" heten.
 *
 *  LUI GEBOUWD, en dat is geen stijlkeuze: `AANHECHT_PREDS` staat verderop in
 *  dit bestand, dus een `new Set([...AANHECHT_PREDS])` op modulehoogte leest
 *  hem in zijn temporal dead zone. Dezelfde reden waarom `regelOpties` hem pas
 *  in zijn body aanspreekt. */
let klimPreds = null;
const KLIM_PREDS = () => (klimPreds
  || (klimPreds = new Set([...AANHECHT_PREDS, ODRL + 'action'])));

/** DE WORTEL(S) BOVEN EEN HOUDER, als namen. Klim zo ver omhoog als de
 *  aanhechtingen reiken en noem wat er bovenaan staat: vanaf een regel is dat
 *  het beleidsstuk, vanaf een plicht onder een regel is dat nog steeds het
 *  beleidsstuk, en vanaf een COLLECTIE — waar niets boven hangt — de collectie
 *  zelf. Dat laatste is geen uitzondering maar dezelfde regel: de herkomst is
 *  het grootste ding dat deze voorwaarde draagt.
 *
 *  `gezien` wordt over alle houders van één voorwaarde gedeeld: twee regels in
 *  hetzelfde beleid delen hun bovenkant, en die hoeft maar één keer gelopen. */
function houderWortels(store, houder, uit, gezien) {
  const k = nn(houder);
  if (!k || gezien.has(k.value)) return;
  gezien.add(k.value);
  let hoger = false;
  for (const q of store.getQuads(null, null, k, null)) {
    if (!KLIM_PREDS().has(q.predicate.value)) continue;
    hoger = true;
    houderWortels(store, q.subject, uit, gezien);
  }
  if (hoger) return;
  const naam = labelFor(store, k);
  if (naam && !uit.includes(naam)) uit.push(naam);
}

/** DE BENOEMDE VOORWAARDEN UIT ÁLLE GELADEN BRONNEN, met hun label, hun curie
 *  en hun HERKOMST — dezelfde vorm als `regelOpties`, en om dezelfde reden: twee
 *  voorwaarden heten in dit domein makkelijk allebei "Alleen voor nazorg", en
 *  dan is "waar hangt zij nu" het enige verschil dat de lezer ziet vóórdat hij
 *  kiest.
 *
 *  ÉÉN VLAKKE LIJST en geen indeling per soort. Bij de regels is die indeling
 *  onvermijdelijk (het koppelpredicaat dwingt de klasse af); hier past elke
 *  voorwaarde op elke voorwaardeplek, dus een tweedeling zou een verschil
 *  suggereren dat er niet is.
 *
 *  BLANKE VOORWAARDEN STAAN ER NIET BIJ: er is niets om aan te wijzen. Dat is
 *  dezelfde grens als bij de regels, met dezelfde uitweg — geef haar eerst een
 *  naam (`benoemKnoop`).
 *
 *  Gesorteerd op label met dezelfde `localeCompare`-collatie als `regelOpties`
 *  en `termOptions`: wie een lijst afkapt op N treffers, kapt hem alfabetisch af. */
export function voorwaardeOpties(store) {
  const kandidaten = new Map();
  for (const pred of VOORWAARDE_PREDS) {
    for (const q of store.getQuads(null, namedNode(pred), null, null)) {
      if (q.object.termType === 'NamedNode') kandidaten.set(q.object.value, q.object);
    }
  }
  for (const klasse of VOORWAARDE_KLASSEN) {
    for (const q of store.getQuads(null, namedNode(RDF + 'type'), namedNode(klasse), null)) {
      if (q.subject.termType === 'NamedNode') kandidaten.set(q.subject.value, q.subject);
    }
  }
  const uit = [];
  for (const [iri, t] of kandidaten) {
    if (!isVoorwaarde(store, t)) continue;
    const herkomst = [];
    const gezien = new Set();
    for (const q of store.getQuads(null, null, t, null)) {
      if (!VOORWAARDE_PREDS.includes(q.predicate.value)) continue;
      houderWortels(store, q.subject, herkomst, gezien);
    }
    uit.push({ iri, curie: curie(iri), label: labelFor(store, t), herkomst });
  }
  return uit.sort((a, b) => a.label.localeCompare(b.label, 'nl'));
}

/** MAG DEZE KOPPELING? Dezelfde vier weigeringen als `koppelToets`, met
 *  dezelfde volgorde en dezelfde reden per stuk:
 *  `ongeldig` (geen bruikbare IRI-tekst), `onbekend` (die knoop staat niet in de
 *  graaf — koppelen zou een dode verwijzing leggen), `alGekoppeld` (de triple
 *  staat er al; een tweede zou niets doen en wél een ↶-stap kosten) en
 *  `verkeerdeSoort` — die laatste dekt hier TWEE dingen: de knoop is geen
 *  voorwaarde, óf het predicaat is geen voorwaardeplek (koppelen onder
 *  `odrl:permission` zou van een voorwaarde stil een regel maken).
 *
 *  Op de LEESgraaf te stellen, om dezelfde reden als `hernoemToets`: een
 *  afgewezen keuze mag geen lege mutatiegroep en dus geen dode ↶ opleveren. */
export function koppelVoorwaardeToets(store, houderTerm, predIri, voorwaardeIri) {
  const iri = expandIri(String(voorwaardeIri || '').trim());
  if (!iri || !geldigeIriTekst(iri)) return { ok: false, reden: 'ongeldig' };
  const v = namedNode(iri);
  if (!store.getQuads(v, null, null, null).length
      && !store.getQuads(null, null, v, null).length) {
    return { ok: false, reden: 'onbekend' };
  }
  const h = nn(houderTerm);
  if (!h) return { ok: false, reden: 'onbekend' };
  if (store.getQuads(h, namedNode(predIri), v, null).length) {
    return { ok: false, reden: 'alGekoppeld' };
  }
  if (!VOORWAARDE_PREDS.includes(predIri) || !isVoorwaarde(store, v)) {
    return { ok: false, reden: 'verkeerdeSoort' };
  }
  return { ok: true };
}

/** DE KOPPELING ZELF: één triple erbij, en verder niets — de voorwaarde wordt
 *  niet aangeraakt en niet gekopieerd. `{ ok: true, term }` of het oordeel van
 *  `koppelVoorwaardeToets`. Eén undo-stap is de zorg van de aanroeper
 *  (`voerUit(..., { groep: true })`), net als bij `koppelRegel`. */
export function koppelVoorwaarde(store, houderTerm, predIri, voorwaardeIri) {
  const oordeel = koppelVoorwaardeToets(store, houderTerm, predIri, voorwaardeIri);
  if (!oordeel.ok) return oordeel;
  const v = namedNode(expandIri(String(voorwaardeIri).trim()));
  store.addQuad(nn(houderTerm), namedNode(predIri), v);
  return { ok: true, term: v };
}

// Nieuwe (doel-)permission aan een policy hangen.
export function addPermission(store, policyTerm, opts = {}) {
  return addRule(store, policyTerm, { klasse: 'Permission', pred: 'permission' }, opts);
}

// Nieuw verbod aan een policy hangen (taak 9f). Zelfde vorm en zelfde opties
// als addPermission: de ghost-chip "+ verbod" naast "+ toestemming" hoort
// hetzelfde op te leveren, alleen van de andere regelsoort.
export function addProhibition(store, policyTerm, opts = {}) {
  return addRule(store, policyTerm, { klasse: 'Prohibition', pred: 'prohibition' }, opts);
}

// Nieuwe duty/obligation aan een policy of permission hangen.
export function addDuty(store, parentTerm, predIri = ODRL + 'obligation') {
  const d = mintBlank(store);
  const a = mintBlank(store);
  store.addQuad(d, namedNode(RDF + 'type'), namedNode(ODRL + 'Duty'));
  // GEEN VERZONNEN NAAM (eigenaarsbevinding 9 sep 2026, tweede ronde). Hier
  // stond `rdfs:label "Nieuwe verplichting"@nl`, en die tekst stond in de
  // bewerkstand als INGEVULDE waarde in het naamveld van de verse rij —
  // dezelfde familie als "Nieuw aanbod" bij `createSkeleton` hieronder. De rij
  // blijft herkenbaar zonder: `readDuty` noemt haar naar haar actie
  // ("Informeren"), en het naamveld staat leeg met zijn hint.
  //
  // DE ACTIE-PREFILL BLIJFT WEL STAAN, en dat is geen inconsequentie maar de
  // eigenaarsregel zelf: prefillen mag, vastzetten niet. `odrl:inform` is wat
  // een verplichting in dit profiel in de overgrote meerderheid van de gevallen
  // is, hij staat in een bewerkbaar veld (`actieRij` toont hem in de
  // bewerkstand altijd), en anders dan een naam is hij geen TEKST die iemand
  // zou moeten hebben getypt.
  store.addQuad(a, namedNode(RDF + 'value'), namedNode(ODRL + 'inform'));
  store.addQuad(d, namedNode(ODRL + 'action'), a);
  store.addQuad(nn(parentTerm), namedNode(predIri), d);
  return d;
}

// --- Partijen ---------------------------------------------------------------

/** DE BASIS-IRI VAN EEN NIEUWE GROEP, afgeleid van de knoop waar hij aan komt
 *  te hangen: `…/beleid` → `…/groep`.
 *
 *  DE TWEEDE TAK IS HET VERSCHIL MET `addAgreement`, die dezelfde afleiding met
 *  een kale `replace(/[#/][^#/]*$/, '/')` doet. Draagt de IRI géén scheidingsteken
 *  — `urn:aanbod`, en dat is een gewone vorm in dit corpus — dan verandert die
 *  replace niets en plakt het woord er zonder grens tegenaan
 *  (`urn:aanbodovereenkomst`). Hier wordt het dan een FRAGMENT (`urn:aanbod#groep`):
 *  een geldige IRI die zichtbaar bij zijn beleid hoort en die `curie` netjes
 *  afkort. `addAgreement` blijft ongemoeid — dat is niet de bevinding van deze
 *  ronde, en zijn vorm zit in vastgelegde toetsen. */
function groepBasis(iri) {
  return iriBasis(iri, 'groep');
}

/** DE ALGEMENE VORM VAN `groepBasis`: dezelfde afleiding, met het woord als
 *  parameter. `naamSuggestie` (het naam-voorstel voor een blanke knoop, verderop)
 *  doet exact hetzelfde met `permission`/`duty`/`constraint` in plaats van
 *  `groep`, en de valkuil die de noot hierboven beschrijft — een IRI zonder `#`
 *  of `/` waar `replace` het woord zonder grens tegenaan plakt — is daar precies
 *  even scherp. Eén afleiding dus, twee aanroepers. */
function iriBasis(iri, woord) {
  const m = /^(.*[#/])[^#/]*$/.exec(iri);
  return m ? m[1] + woord : iri + '#' + woord;
}

/** EEN NIEUWE GROEP ALS PARTIJ: mint een `odrl:PartyCollection` en koppel hem
 *  op (subject, predicaat) — de afnemer- of aanbiederrelatie waar hij komt te
 *  staan.
 *
 *  EIGENAARSBEVINDING 9 SEP 2026, letterlijk: "Als hij er wel een heeft is een
 *  PartyCollection met refinements ook niet aan te maken." Het één-bewerkbron-/
 *  V14-spoor staat zo'n groep als partij toe, de LEESkant toont hem al (de
 *  collectiekaart met haar "Afbakening"-sectie, `ui/kaart/collectie.tsx`) en de
 *  kaart is bewerkbaar — maar hij kon alleen ONTSTAAN door hem in de bron te
 *  typen. Dit is die ontbrekende aanmaakroute, als één mutatie zodat de UI hem
 *  in één undo-stap kan uitvoeren.
 *
 *  DE IRI VOLGT `mintIri` WAAR DAT KAN. Een groep is een knoop waar anderen
 *  naar gaan verwijzen (een tweede regel, een tweede beleid), en dan is een
 *  benoemde knoop het verschil tussen herbruikbaar en niet. Draagt het subject
 *  zelf geen IRI — een blanke regel, een blanke policy — dan is er geen basis om
 *  van af te leiden en valt hij terug op `mintBlank`: dezelfde ladder als elders
 *  in dit bestand, en nooit de naamloze `blankNode()`.
 *
 *  DE PARTIJ DIE ER STOND WORDT HET EERSTE LID, en dat is de kern van de tweede
 *  helft van de bevinding. De alternatieven waren allebei slechter: hem
 *  stilzwijgend VERVANGEN gooit een uitspraak weg die iemand deed, en de knop
 *  UITZETTEN zolang er een afnemer staat laat precies het geval onopgelost dat de
 *  eigenaar noemt. De koppeling is `lid odrl:partOf groep` — de ODRL-kernrichting
 *  die `collectionMembers` (parse.js) als primair leest, dus de oude partij staat
 *  meteen als lid in de ledenlijst van de nieuwe groep. Alleen een BENOEMDE
 *  partij verhuist mee: een blanke partij heeft geen identiteit om als lid te
 *  tonen (`collectionMembers` slaat hem over) en zou een onzichtbaar lid worden.
 *
 *  WAT DEZE FUNCTIE NIET DOET: een naam of een afbakening verzinnen. Een verse
 *  groep is naamloos en onafgebakend, en zegt dat ook — de weergave toont het
 *  lege naamveld met zijn hint en de lege "Afbakening"-sectie met haar ghost.
 *  Dezelfde regel als bij `addRule`, `addDuty` en `createSkeleton`. */
export function addPartyCollection(store, subject, predIri) {
  const s = nn(subject);
  const coll = s.termType === 'NamedNode'
    ? namedNode(mintIri(store, groepBasis(s.value))) : mintBlank(store);
  store.addQuad(coll, namedNode(RDF + 'type'), namedNode(ODRL + 'PartyCollection'));
  for (const oud of objsOf(store, s, predIri)) {
    if (oud.termType === 'NamedNode') store.addQuad(oud, namedNode(ODRL + 'partOf'), coll);
  }
  removeProp(store, s, predIri);
  store.addQuad(s, namedNode(predIri), coll);
  return coll;
}

/** IS DEZE KNOOP AL EEN GROEP? De toets waarop de UI haar "+ groep"-knop uitzet:
 *  een tweede groep om een groep heen is geen antwoord op "ik wil deze afnemer
 *  afbakenen" — de afbakening hoort dan aan de bestaande groep. Alleen de
 *  ODRL-kerntypen tellen; `collectionKind` in parse.js doet dezelfde lezing voor
 *  de weergave. */
export function isPartyCollection(store, term) {
  if (!store || !term) return false;
  return objsOf(store, nn(term), RDF + 'type')
    .some((t) => t.value === ODRL + 'PartyCollection' || t.value === ODRL + 'AssetCollection');
}

// Nieuwe Agreement op een bestaand Offer (assigner en target overgenomen).
//
// GEEN TITEL EN GEEN BESCHRIJVING (eigenaarsbevinding 9 sep 2026, tweede
// ronde). Hier stonden `dct:title "Nieuwe overeenkomst"` — achter een
// `opts.title` die geen enkele aanroeper ooit vulde, dus een schakelaar met één
// stand — en een instructie-alinea als `dct:description`. Beide waren tekst die
// niemand schreef, en beide stonden in de bewerkstand als INGEVULDE waarde in
// hun veld. Zie `createSkeleton` voor de volle redenering en voor wat er in de
// plaats komt (een leeg veld met zijn hint in het `placeholder`-attribuut).
//
// DE LOCALNAME IS DE TERUGVAL van de weergave, en daarom heet de geminte IRI
// sinds deze ronde `…/overeenkomst` en niet `…/overeenkomst-nieuw`: zonder eigen
// titel toont `labelFor` de localName, en die hoort als gewoon Nederlands woord
// te lezen. `mintIri` maakt er bij een tweede overeenkomst vanzelf
// "overeenkomst-2" van — twee naamloze kaarten blijven zo in de navigatie uit
// elkaar te houden.
export function addAgreement(store, offerTerm) {
  const offer = nn(offerTerm);
  const base = offer.value.replace(/[#/][^#/]*$/, '/');
  const iri = mintIri(store, base + 'overeenkomst');
  const agr = namedNode(iri);
  store.addQuad(agr, namedNode(RDF + 'type'), namedNode(ODRL + 'Agreement'));
  store.addQuad(agr, namedNode(DCT + 'issued'), literal(today(), namedNode(XSD + 'date')));
  store.addQuad(agr, namedNode(ODRL + 'profile'), namedNode(DEFAULT_PROFILE));
  store.addQuad(agr, namedNode(ODRL + 'uid'), agr);
  // Koppeling aan het Offer via de standaardrelatie uit PROFILE_PATTERNS:
  // prov:wasDerivedFrom (MOET; niveau-2-shape). Eén predicaat — het eerdere
  // duplicaat dct:references naar hetzelfde aanbod wordt niet meer geschreven.
  for (const pred of PROFILE_PATTERNS.agreementOfferPreds) {
    store.addQuad(agr, namedNode(pred), offer);
  }
  // DE AANBIEDER WORDT OVERGENOMEN, NIET VERZONNEN: staat hij op het aanbod, dan
  // weet deze aanroeper hem echt. Staat hij er niet, dan blijft de relatie weg.
  const assigner = objOf(store, offer, ODRL + 'assigner');
  if (assigner) store.addQuad(agr, namedNode(ODRL + 'assigner'), assigner);
  // GEEN AFNEMER-PLAATSHOUDER (eigenaarsbevinding 9 sep 2026). Hier stonden twee
  // regels: een geminte IRI `…/afnemer-nieuw` en daarop het label
  // "(vul afnemer in)". Allebei zijn ze een uitspraak in de DATA die niemand
  // deed — dezelfde soort verzinsel als de doelknoop die 8 sep sneuvelde, alleen
  // dan met een IRI erbij. In de bewerkstand kwam dat label als INGEVULDE TEKST
  // in het afnemer-veld te staan, en dat is wat de eigenaar zag: "Placeholders
  // als (vul aanbieder in) op allerlei plekken zijn echt tekst in het invoerveld
  // i.p.v. subtle hints die verdwijnen als je begint te typen."
  //
  // WAAROM NIET "DE KNOOP HOUDEN, HET LABEL WEG". Dan blijft er een geminte
  // partij-IRI staan waarvan de weergave de localName toont ("afnemer-nieuw"),
  // dus staat er nog steeds tekst in het veld — en erger: de MOET-shape
  // (`sh:minCount 1`, `sh:nodeKind sh:IRI` op odrl:assignee) zou "gehaald" zijn
  // door een partij die niet bestaat. Dat is verzonnen conformiteit. Een verse
  // overeenkomst IS onvolledig; zij hoort dat te zeggen. De WEG ernaartoe staat
  // in de bewerkstand: de Afnemer-rij staat er ook zonder waarde, als leeg veld
  // met zijn hint (`agreementRijen` in ui/kaart/body-rijen.tsx).
  // Target van de eerste offer-permission overnemen als die er is.
  let targetIri = null;
  const firstPerm = objOf(store, offer, ODRL + 'permission');
  if (firstPerm) {
    const t = objOf(store, firstPerm, ODRL + 'target');
    if (t && t.termType === 'NamedNode') targetIri = t.value;
  }
  // ZONDER DOEL-PLAATSHOUDER (eigenaarsbesluit 8 sep 2026, fixronde 1). Hier
  // stond `withPurpose: true` — hardcoded, niet doorgegeven door een aanroeper —
  // en dat was toen de laatste plek waar de nep-doelknoop ("(vul doel in)", met
  // een geminte IRI) nog automatisch ontstond. Sinds 9 sep bestaat die tak
  // helemaal niet meer (zie `addRule`), dus er valt hier ook niets meer uit te
  // zetten: een verse regel is leeg tenzij de aanroeper iets meegeeft.
  //
  // De reden dat hij vervalt is dezelfde als bij de kaart-ghost (verfijning 1c):
  // in een gegroepeerde weergave levert zo'n regel een dimensievakje op dat
  // niemand aanwees, en in de data een doel dat niemand koos. Er is geen
  // "een skelet moet iets tonen"-argument dat hier standhoudt en dat niet
  // evengoed voor die ghost gold — en anders dan `odrl:assigner`/`assignee` is
  // `odrl:purpose` geen MOET-relatie van het profiel die het drietraps draagt.
  // De weg ernaartoe staat in de verse regel zelf: de snelkoppeling naar de
  // groeperingsvoorwaarde (`VoorwaardeGhost`, ui/bewerk/integratie/rij-bewerk.tsx).
  addPermission(store, agr, { targetIri });
  return iri;
}

// Zet de Offer-koppeling van een Agreement (prov:wasDerivedFrom). Dat predicaat
// draagt ook ándere verwijzingen (wettelijke grondslag, documenten); daarom
// worden alleen bestaande waarden verwijderd die een bekend Offer zijn
// (knownOfferIris: iterable van Offer-IRI's). Lege offerIri = koppeling
// weghalen. Bij het opruimen loopt óók het historische duplicaat
// dct:references mee (legacyAgreementOfferPreds): bestanden van vóór de
// schoning dragen het nog, en een omgehangen koppeling mag geen wees achterlaten.
export function setAgreementOffer(store, agrTerm, offerIri, knownOfferIris) {
  const known = knownOfferIris instanceof Set ? knownOfferIris : new Set(knownOfferIris || []);
  const opruimen = [...PROFILE_PATTERNS.agreementOfferPreds,
    ...PROFILE_PATTERNS.legacyAgreementOfferPreds];
  for (const pred of opruimen) {
    for (const q of store.getQuads(nn(agrTerm), namedNode(pred), null, null)) {
      if (q.object.termType === 'NamedNode' && known.has(q.object.value)) store.removeQuad(q);
    }
  }
  const full = expandIri(offerIri);
  if (!full) return;
  for (const pred of PROFILE_PATTERNS.agreementOfferPreds) {
    store.addQuad(nn(agrTerm), namedNode(pred), namedNode(full));
  }
}

// Leeg drietraps-skelet: Offer + Agreement + Permission met verplichte
// basiselementen en profieldeclaratie voorgevuld.
export function createSkeleton(store, base = 'https://beleid.example.gov.nl/nieuw/') {
  const offerIri = mintIri(store, base + 'aanbod');
  const offer = namedNode(offerIri);
  // GEEN AANBIEDER- EN GEGEVENSBRON-PLAATSHOUDER (eigenaarsbevinding 9 sep
  // 2026). Hier werden twee knopen gemint — `…/aanbieder` en
  // `…/gegevensbron` — met de labels "(vul aanbieder in)" en "(vul
  // gegevensbron in)", en die labels stonden vervolgens als INGEVULDE TEKST in
  // het aanbieder-veld en in de doelobject-tag. De redenering staat voluit bij
  // `addAgreement` hierboven; in het kort: een plaatshouder hoort in de UI
  // (het `placeholder`-attribuut van het invoerveld, dat verdwijnt zodra je
  // typt) en niet in de graaf.
  //
  // EN SINDS DE TWEEDE RONDE OOK GEEN TITEL EN GEEN BESCHRIJVING. Hier stond
  // `dct:title "Nieuw aanbod"@nl` en een `dct:description` met de invulzin
  // "Beschrijf hier het aanbod (welke gegevens, aan wie, onder welke
  // standaardvoorwaarden)." Eigenaar, letterlijk: "Aanbod, toestemming en
  // verbod hebben nog steeds geen placeholders bij nieuwe aanmaken" — precies
  // omdat die twee zinnen als INGEVULDE waarde in het titel- en het
  // beschrijvingsveld stonden en een `placeholder` per definitie onzichtbaar is
  // zolang er een waarde staat. Het is dezelfde familie als de "(vul … in)"-
  // labels: tekst die niemand schreef, in de data.
  //
  // WAT ER VOOR IN DE PLAATS KOMT staat in de UI: het titelveld en het
  // beschrijvingsveld staan leeg met hun hint in het `placeholder`-attribuut
  // (`edit.hintTitel`/`edit.hintBeschrijving`, via `VeldSpec.hint`), en het
  // beschrijvingsveld staat er in de bewerkstand ook zónder waarde — anders zou
  // een kaart zonder beschrijving er geen meer kunnen krijgen.
  //
  // BLIJFT EEN NAAMLOZE KAART HERKENBAAR? Ja, en dat is met opzet niet met een
  // tweede verzinsel opgelost: `labelFor` valt zonder eigen naam terug op de
  // localName van de knoop, dus de kaart heet "aanbod" (en de tweede
  // "aanbod-2", want `mintIri` telt door). Dat is geen uitspraak in de data —
  // het is de knoop-IRI, die er echt staat — en het houdt twee naamloze kaarten
  // in de lijst en in de navigatie uit elkaar, wat een vaste tekst als "(nog
  // geen titel)" juist niet zou doen.
  store.addQuad(offer, namedNode(RDF + 'type'), namedNode(ODRL + 'Offer'));
  store.addQuad(offer, namedNode(DCT + 'issued'), literal(today(), namedNode(XSD + 'date')));
  store.addQuad(offer, namedNode(ODRL + 'profile'), namedNode(DEFAULT_PROFILE));
  store.addQuad(offer, namedNode(ODRL + 'uid'), offer);
  // Zonder aanbieder-knoop is er ook geen odrl:assigner en geen odrl:target: de
  // eerste toestemming ontstaat leeg, precies zoals elke andere verse regel
  // (zie `addRule`). Wat het skelet wél voorvult is wat het ECHT weet — soort,
  // titel, beschrijving, datum, profiel en uid.
  addPermission(store, offer);

  const agreementIri = addAgreement(store, offer);
  return { offerIri, agreementIri };
}

// Dupliceer een benoemde policy (Offer/Agreement): sluiting kopiëren met verse
// blank nodes, zelfverwijzingen (uid) herschreven, titel + " (kopie)".
export function duplicatePolicy(store, term, newIri) {
  const t = nn(term);
  const iri = newIri || mintIri(store, t.value + '-kopie');
  const root = namedNode(iri);
  const bmap = new Map();
  const mt = (x) => {
    if (x.termType === 'BlankNode') {
      if (!bmap.has(x.value)) bmap.set(x.value, mintBlank(store));
      return bmap.get(x.value);
    }
    if (x.termType === 'NamedNode' && x.value === t.value) return root;
    return x;
  };
  for (const q of closureQuads(store, t)) store.addQuad(mt(q.subject), q.predicate, mt(q.object));
  // "(kopie)" hoort op de naam die de WEERGAVE toont, en die staat niet altijd
  // op dct:title: een verplichting draagt haar naam op rdfs:label (zo leest
  // parse.js hem, zo schrijft addDuty hem). Alleen dct:title merken zou een
  // gedupliceerde plicht als exacte tweeling van het origineel achterlaten —
  // twee identieke rijen, niet uit elkaar te houden. Dezelfde
  // voorkeursvolgorde als de weergave: dct:title als die er is, anders
  // rdfs:label.
  const naamPred = [DCT + 'title', RDFS + 'label']
    .find((p) => store.getQuads(root, namedNode(p), null, null).length);
  for (const q of (naamPred ? store.getQuads(root, namedNode(naamPred), null, null) : [])) {
    store.removeQuad(q);
    store.addQuad(root, q.predicate, literal(q.object.value + ' (kopie)', q.object.language || undefined));
  }
  return iri;
}

// Dupliceer een aangehangen node (permission/duty/constraint) binnen dezelfde ouder.
export function duplicateAttached(store, parentTerm, predIri, term) {
  const t = nn(term);
  const bmap = new Map();
  const mt = (x) => {
    if (x.termType === 'BlankNode') {
      if (!bmap.has(x.value)) bmap.set(x.value, mintBlank(store));
      return bmap.get(x.value);
    }
    return x;
  };
  if (t.termType === 'BlankNode') {
    for (const q of closureQuads(store, t)) store.addQuad(mt(q.subject), q.predicate, mt(q.object));
    const copy = mt(t);
    store.addQuad(nn(parentTerm), namedNode(predIri), copy);
    return copy;
  }
  // Benoemde node: alleen een extra verwijzing is zinloos; kopieer als nieuwe IRI.
  const iri = duplicatePolicy(store, t);
  store.addQuad(nn(parentTerm), namedNode(predIri), namedNode(iri));
  return namedNode(iri);
}

// --- Wees-realisatielinks (taak 7) ------------------------------------------
//
// Een ANKER verwijst met prov:wasDerivedFrom naar de knoop die het realiseert
// (de technische borging naar de voorwaarde/plicht die zij afdwingt). Dat is
// geen GEBRUIK van die knoop: er hangt geen regel aan, er staat niets in het
// beleid dat hem nodig heeft. Telt zo'n link tóch als gebruiker mee, dan laat
// het losmaken een knoop achter waar niets meer naartoe leidt behalve die ene
// link — onzichtbaar in de weergave, en in het TTL een wees die bij elke
// volgende lading meekomt.
//
// Vandaar deze aparte opruimer, en de filtering in removeAttached hieronder.
// LOSMAKEN (er is nog wél een echte gebruiker) laat de links met opzet staan:
// de knoop blijft dan bestaan en de realisatie klopt nog steeds.
const REALISATIE_PRED = PREFIXES.prov + 'wasDerivedFrom';

export function verwijderInkomendeRealisaties(store, term) {
  const weg = store.getQuads(null, namedNode(REALISATIE_PRED), nn(term), null);
  store.removeQuads(weg);
  return weg.length;
}

// De predicaten waarmee een REGEL of PLICHT aan een policy (of aan elkaar)
// hangt. Nodig om te weten wat er bij een policy hoort: haar blanke knopen
// zitten in de sluiting, maar een BENOEMDE regel of plicht niet.
export const AANHECHT_PREDS = [
  ODRL + 'permission', ODRL + 'prohibition', ODRL + 'obligation',
  ODRL + 'duty', ODRL + 'consequence',
];

// WAT KOST HET VERWIJDEREN VAN DEZE POLICY? Alle quads die removePolicy
// wegneemt, als lijst — zonder iets te muteren. De UI heeft die lijst nodig
// om vóóraf te kunnen zeggen of de bewerking helemaal in een schrijfbron valt
// (een half uitgevoerde verwijdering laat fragmenten in alleen-lezen bronnen
// achter, en de delta zou naar een graph gaan die niet te schrijven is).
// Eén bron van waarheid dus: removePolicy verwijdert exact deze lijst.
//
// Wat er in zit:
//   1. de SLUITING van de policy zelf (met haar blanke knopen);
//   2. alle INKOMENDE verwijzingen ernaartoe (dcat:hasPolicy, de
//      prov:wasDerivedFrom van een overeenkomst, dct:references) — anders
//      blijven die als dangling verwijzing achter;
//   3. de BENOEMDE regels en plichten die alleen aan deze policy hangen, met
//      hun eigen sluiting, inkomende verwijzingen en (recursief) hun eigen
//      benoemde kinderen. Zonder die stap belooft "dit beleid met alle regels
//      en verplichtingen" iets wat niet gebeurt: de kaart verdwijnt en de
//      regels blijven als onbereikbare wezen in het bestand staan. Een regel
//      die ELDERS ook gebruikt wordt blijft uiteraard staan — realisatielinks
//      tellen daarbij niet als gebruiker (zie hierboven).
//
// De lijst is ONTDUBBELD: de koppeling ouder→kind (odrl:permission en
// verwanten) komt twee keer langs — één keer in de sluiting van de ouder en
// één keer in de inkomende-verwijzing-sweep van het kind. Wie de lijst telt
// (de UI, om te melden hoeveel er weggaat) of als delta doorgeeft aan de
// bron-sync moet elk quad één keer zien; removeQuads zelf gaf al het goede
// resultaat, maar de telling niet.
export function policyWisQuads(store, term) {
  const t = nn(term);
  const weg = [];
  const wegSleutels = new Set();
  const voegToe = (q) => {
    const k = N3.termToId(q.subject) + '\u0000' + N3.termToId(q.predicate)
      + '\u0000' + N3.termToId(q.object) + '\u0000' + N3.termToId(q.graph);
    if (wegSleutels.has(k)) return;
    wegSleutels.add(k);
    weg.push(q);
  };
  const gepland = new Set();
  const sleutel = (x) => x.termType + ':' + x.value;
  const wis = (node) => {
    if (gepland.has(sleutel(node))) return;
    gepland.add(sleutel(node));
    // Eerst de benoemde kinderen noteren: na het wissen is de koppeling weg.
    const kinderen = [];
    for (const pred of AANHECHT_PREDS) {
      for (const q of store.getQuads(node, namedNode(pred), null, null)) {
        if (q.object.termType === 'NamedNode') kinderen.push(q.object);
      }
    }
    for (const q of store.getQuads(null, null, node, null)) voegToe(q);
    for (const q of closureQuads(store, node)) voegToe(q);
    for (const k of kinderen) {
      const anderen = store.getQuads(null, null, k, null).filter((q) => {
        if (q.predicate.value === REALISATIE_PRED) return false;         // realisatie
        if (q.subject.termType === k.termType && q.subject.value === k.value) return false;
        return !gepland.has(sleutel(q.subject));                          // gaat zelf weg
      });
      if (!anderen.length) wis(k);
    }
  };
  wis(t);
  return weg;
}

// Verwijder een benoemde policy: alles wat policyWisQuads opsomt.
export function removePolicy(store, term) {
  store.removeQuads(policyWisQuads(store, term));
}

// Maak een aangehangen node los; ruim de sluiting op als niets er meer naar
// verwijst (gedeelde benoemde constraints/duties blijven dus staan).
// Zelfverwijzingen (bv. odrl:uid naar zichzelf) tellen niet als verwijzing.
export function removeAttached(store, parentTerm, predIri, term) {
  const t = nn(term);
  store.removeQuads(store.getQuads(nn(parentTerm), namedNode(predIri), t, null));
  const external = store.getQuads(null, null, t, null)
    .filter((q) => !(q.subject.termType === t.termType && q.subject.value === t.value))
    // Realisatielinks tellen niet als gebruiker: zie verwijderInkomendeRealisaties.
    .filter((q) => q.predicate.value !== REALISATIE_PRED);
  if (external.length === 0) {
    verwijderInkomendeRealisaties(store, t);
    store.removeQuads(store.getQuads(null, null, t, null));
    store.removeQuads(closureQuads(store, t));
  }
}

// --- Een knoop hernoemen (testronde 9 sep 2026, punt 3) ---------------------
//
// EIGENAAR, LETTERLIJK: "Ik kan de node-id niet editen."
//
// PARITEIT: de bevroren viewer (viewer-bevroren/assets/doc.js, viewer-bevroren/assets/edit.js)
// kent geen enkele route om de IRI van een knoop te wijzigen — `mintIri` en
// `duplicatePolicy` MAKEN er een, niemand HERNOEMT er een. Dit is dus geen
// pariteitsherstel maar een GELABELDE VERBETERING op eigenaarsverzoek, met dit
// citaat als reden.
//
// WAAROM DIT ÉÉN MUTATIE IS EN GEEN VELD. Een IRI is geen waarde ván een knoop
// maar zijn NAAM: hij staat in elke triple waarin de knoop voorkomt, als subject
// én als object, en in de verwijzingen vanuit andere policies (odrl:uid naar
// zichzelf, prov:wasDerivedFrom vanuit een overeenkomst, dcat:hasPolicy vanuit
// een dataset). Een `setIri` op één predicaat zou daar één plek van veranderen
// en de rest laten wijzen naar een knoop die niet meer bestaat. Half hernoemen
// is erger dan niet hernoemen — dus: alle posities, of geen.
//
// DRIE WEIGERINGEN, elk met een reden die de UI kan tonen:
//   - `ongeldig`  — geen bruikbare IRI-tekst (`geldigeIriTekst`). Zonder deze
//     toets belandt "Gemeente Vlierdam" als <Gemeente Vlierdam> in de bron en is
//     die bij de volgende lading niet meer te parsen;
//   - `bezet`     — de nieuwe IRI is al in gebruik. Doorgaan zou twee knopen tot
//     één samensmelten, en dat is geen hernoeming maar een fusie die niemand
//     vroeg (en die geen undo-stap netjes uit elkaar haalt);
//   - `onbekend`  — de oude IRI komt in de graaf niet voor; er valt niets te
//     hernoemen en een stille no-op zou als succes voelen.
//
// De UI toetst daarnaast of alle geraakte quads in de BEWERKBRON staan — zie
// `hernoemQuads` hieronder, dezelfde vorm als `policyWisQuads` bij het ✕.

/** ALLE QUADS DIE DEZE HERNOEMING RAAKT: de knoop als subject, plus elke
 *  verwijzing naar hem als object. Zonder iets te muteren, en ONTDUBBELD — een
 *  zelfverwijzing (`odrl:uid` naar de eigen IRI) komt langs beide kanten voorbij,
 *  en de UI die deze lijst telt of als bewerkbron-toets gebruikt moet elk quad
 *  één keer zien.
 *
 *  Eén bron van waarheid, net als bij `policyWisQuads`: `hernoemKnoop` herschrijft
 *  exact deze lijst, dus de toets vooraf en de mutatie kunnen niet uit elkaar
 *  lopen. */
export function hernoemQuads(store, iri) {
  return knoopPosities(store, namedNode(expandIri(iri)));
}

/** DE POSITIES VAN ÉÉN KNOOP — hij als subject, plus elke verwijzing naar hem
 *  als object, ontdubbeld.
 *
 *  Dit is de kern van `hernoemQuads` hierboven, apart gezet omdat de PROMOTIE van
 *  een blanke knoop (`benoemKnoop`, hieronder) exact dezelfde lijst nodig heeft en
 *  er niets is dat de twee anders maakt: een naam verzetten is een naam
 *  verzetten, of de oude nu een IRI was of niets. Twee kopieën zouden op de dedup
 *  of op de graph-behandeling uit elkaar gaan lopen, en dat is precies waar "half
 *  hernoemd" ontstaat. */
export function knoopPosities(store, term) {
  const t = nn(term);
  const uit = [];
  const gezien = new Set();
  const voegToe = (q) => {
    const k = N3.termToId(q.subject) + '\u0000' + N3.termToId(q.predicate)
      + '\u0000' + N3.termToId(q.object) + '\u0000' + N3.termToId(q.graph);
    if (gezien.has(k)) return;
    gezien.add(k);
    uit.push(q);
  };
  for (const q of store.getQuads(t, null, null, null)) voegToe(q);
  for (const q of store.getQuads(null, null, t, null)) voegToe(q);
  return uit;
}

/** DE HERNOEMING ZELF. Levert `{ ok: true, aantal }` of `{ ok: false, reden }`
 *  met een van de drie redenen uit de kop hierboven.
 *
 *  DE GRAPH GAAT MEE. Elk herschreven quad wordt teruggeschreven in de graph
 *  waarin het stond — dezelfde uitzondering die `zetLiteral` gebruikt, en om
 *  dezelfde reden: de schrijf-facade zou een quad zonder graph naar de
 *  werkgraph routeren en het triple zo stil uit zijn eigen bron tillen. Bij een
 *  hernoeming zou dat de knoop over twee bronnen verdelen.
 *
 *  ÉÉN UNDO-STAP is de zorg van de AANROEPER: hij draait deze functie binnen
 *  `voerUit(..., { groep: true })`, precies zoals het ✕ en het ⧉ dat doen. Deze
 *  functie kent de undo-laag niet. */
export function hernoemKnoop(store, oudIri, nieuwIri) {
  const oordeel = hernoemToets(store, oudIri, nieuwIri);
  if (!oordeel.ok || oordeel.aantal === 0) return oordeel;
  const oud = expandIri(oudIri);
  const nieuwT = namedNode(expandIri(nieuwIri));
  const raakt = hernoemQuads(store, oud);
  const om = (x) => (x.termType === 'NamedNode' && x.value === oud ? nieuwT : x);
  store.removeQuads(raakt);
  for (const q of raakt) {
    store.addQuad(om(q.subject), q.predicate, om(q.object), q.graph);
  }
  return { ok: true, aantal: raakt.length };
}

/** MAG DEZE HERNOEMING? Hetzelfde oordeel als `hernoemKnoop`, zonder één quad
 *  aan te raken — `{ ok: true, aantal }` of `{ ok: false, reden }`.
 *
 *  Hij staat er apart omdat de UI hem op de LEESgraaf moet kunnen stellen: de
 *  melding "die IRI is al in gebruik" hoort te verschijnen ZONDER dat er een
 *  mutatiegroep opengaat. Deed de UI dat wel, dan zou elke afgewezen poging een
 *  lege undo-stap opleveren — een ↶ die niets terugdraait is erger dan geen ↶. */
export function hernoemToets(store, oudIri, nieuwIri) {
  const oud = expandIri(oudIri);
  const nieuw = expandIri(nieuwIri);
  if (!nieuw || !geldigeIriTekst(nieuw)) return { ok: false, reden: 'ongeldig' };
  if (!oud) return { ok: false, reden: 'onbekend' };
  if (oud === nieuw) return { ok: true, aantal: 0 };
  const nieuwT = namedNode(nieuw);
  if (store.getQuads(nieuwT, null, null, null).length
      || store.getQuads(null, null, nieuwT, null).length) {
    return { ok: false, reden: 'bezet' };
  }
  const raakt = hernoemQuads(store, oud);
  if (!raakt.length) return { ok: false, reden: 'onbekend' };
  return { ok: true, aantal: raakt.length };
}

// --- Een blanke knoop een naam geven (eigenaarsrichting 9 sep 2026) ---------
//
// EIGENAAR, LETTERLIJK: "En hoe we bestaande nodes kunnen 'namen' natuurlijk."
//
// WAAROM DIT NAAST `hernoemKnoop` STAAT EN ER NIET IN ZIT. De drie weigeringen
// zijn dezelfde en de verhuizing is dezelfde, maar de INGANG is een andere: een
// hernoeming krijgt een IRI-tekst en zoekt de knoop erbij, een promotie krijgt
// de KNOOP zelf — een blanke knoop heeft geen naam om mee te zoeken. Eén functie
// met een tak die van het argumenttype afhangt, is precies hoe de weigering
// "onbekend" stil de verkeerde tak in valt. Wat ze wél delen staat één keer:
// `knoopPosities` hierboven.
//
// DE VIERDE WEIGERING IS NIEUW: `geenBlanke`. Een BENOEMDE knoop hoort hier niet
// binnen te komen — die hernoemt met `hernoemKnoop` — en de omgekeerde richting
// (benoemd → blank) bestaat bewust niet. Een IRI weghalen maakt elke verwijzing
// van buiten dood, en anders dan bij een hernoeming is er geen nieuwe naam om ze
// naartoe te verzetten: het is geen naamswijziging maar een verlies van
// identiteit. Zie de scope-grens in de brief van deze lane.
//
// DE BLANKE KNOPEN ONDER DE KNOOP BLIJVEN BLANK. Alleen de knoop zelf krijgt een
// naam; zijn actie-knoop, zijn voorwaarden en de rest van de sluiting horen bij
// precies één ouder en hebben buiten dit document geen adres nodig. Dat is
// dezelfde grens die `addPartyCollection` trekt (alleen een BENOEMD lid verhuist
// mee) en dezelfde die `closureQuads` niet oversteekt.

/** MAG DEZE KNOOP DEZE NAAM KRIJGEN? `{ ok: true, aantal }` of
 *  `{ ok: false, reden }` met `ongeldig`, `bezet`, `onbekend` of `geenBlanke`.
 *  Raakt geen quad aan — de UI stelt hem op de LEESgraaf, zodat een afgewezen
 *  poging geen lege mutatiegroep en dus geen dode ↶ oplevert. */
export function benoemToets(store, blank, nieuwIri) {
  const t = nn(blank);
  if (!t || t.termType !== 'BlankNode') return { ok: false, reden: 'geenBlanke' };
  const nieuw = expandIri(String(nieuwIri || '').trim());
  if (!nieuw || !geldigeIriTekst(nieuw)) return { ok: false, reden: 'ongeldig' };
  const nieuwT = namedNode(nieuw);
  if (store.getQuads(nieuwT, null, null, null).length
      || store.getQuads(null, null, nieuwT, null).length) {
    return { ok: false, reden: 'bezet' };
  }
  const raakt = knoopPosities(store, t);
  if (!raakt.length) return { ok: false, reden: 'onbekend' };
  return { ok: true, aantal: raakt.length };
}

/** DE PROMOTIE ZELF: alle posities van de blanke knoop krijgen de nieuwe IRI.
 *
 *  DE GRAPH GAAT MEE, om dezelfde reden als bij `hernoemKnoop`: een quad zonder
 *  graph zou door de schrijf-facade naar de werkgraph gerouteerd worden en het
 *  triple stil uit zijn eigen bron tillen.
 *
 *  ÉÉN UNDO-STAP is de zorg van de AANROEPER (`voerUit(..., { groep: true })`),
 *  net als bij het ✕, het ⧉ en de hernoeming. */
export function benoemKnoop(store, blank, nieuwIri) {
  const oordeel = benoemToets(store, blank, nieuwIri);
  if (!oordeel.ok) return oordeel;
  const oud = nn(blank);
  const nieuwT = namedNode(expandIri(String(nieuwIri).trim()));
  const raakt = knoopPosities(store, oud);
  const om = (x) => (x.termType === 'BlankNode' && x.value === oud.value ? nieuwT : x);
  store.removeQuads(raakt);
  for (const q of raakt) {
    store.addQuad(om(q.subject), q.predicate, om(q.object), q.graph);
  }
  return { ok: true, aantal: raakt.length };
}

/** EEN VOORSTEL VOOR DIE NAAM, afgeleid van het beleid waar de knoop in hangt.
 *
 *  De brief van deze lane vraagt er expliciet om: "Suggestie-basis: de
 *  IRI-hiërarchie van het omliggende beleid (zoals groepBasis dat doet)". Dat is
 *  ook de enige basis die er is — een blanke knoop draagt zelf geen enkele
 *  aanwijzing — en zij is dezelfde als die van `addPartyCollection`: neem de
 *  dichtstbijzijnde BENOEMDE knoop die naar deze wijst, en zet er een woord
 *  achter. Het woord is de localName van het TYPE (`permission`, `duty`,
 *  `constraint`): dat is wat de knoop ís, en het is het enige gegeven dat er al
 *  staat — een naam verzinnen uit de inhoud zou een uitspraak zijn die niemand
 *  deed.
 *
 *  DE WANDELING GAAT OMHOOG DOOR BLANKE KNOPEN HEEN: een voorwaarde hangt aan
 *  een actie-knoop die aan een blanke regel hangt die aan een benoemd aanbod
 *  hangt. Zonder die doorloop zou juist de diepste knoop — die de suggestie het
 *  hardst nodig heeft — er geen krijgen.
 *
 *  `mintIri` eromheen, zodat het voorstel per constructie vrij is: een tweede
 *  toestemming onder hetzelfde aanbod krijgt `…#toestemming-2` in plaats van een
 *  voorstel dat de `bezet`-weigering meteen afkeurt. Leeg antwoord = er is geen
 *  benoemde omgeving; dan doet de UI geen voorstel en typt de lezer zelf. */
export function naamSuggestie(store, blank) {
  const t = nn(blank);
  if (!t || t.termType !== 'BlankNode') return '';
  let basis = '';
  const gezien = new Set([t.value]);
  const rij = [t];
  while (rij.length && !basis) {
    const huidig = rij.shift();
    for (const q of store.getQuads(null, null, huidig, null)) {
      if (q.subject.termType === 'NamedNode') { basis = q.subject.value; break; }
      if (q.subject.termType === 'BlankNode' && !gezien.has(q.subject.value)) {
        gezien.add(q.subject.value);
        rij.push(q.subject);
      }
    }
  }
  if (!basis) return '';
  const ty = objOf(store, t, RDF + 'type');
  const woord = ty ? localName(ty.value).toLowerCase() : 'knoop';
  return mintIri(store, iriBasis(basis, woord));
}

// --- Raw-RDF-vangnet (laag 3) -----------------------------------------------

// Vervang de subject-sluiting van `subject` door het gegeven Turtle-fragment.
// Alle bekende prefixes worden voorgedeclareerd (het bronpaneel-fragment mag
// dus ongewijzigd terug). Parsefouten laten de graaf onaangetast.
export function replaceSubjectClosure(store, subject, turtleText) {
  const t = nn(subject);
  const header = Object.entries(allPrefixes()).map(([p, iri]) => `@prefix ${p}: <${iri}> .`).join('\n');
  const headerLines = header.split('\n').length;
  let quads;
  try {
    quads = new Parser().parse(header + '\n' + turtleText);
  } catch (e) {
    const msg = String(e.message || e).replace(/line (\d+)/, (_, n) => 'regel ' + Math.max(1, Number(n) - headerLines));
    return { ok: false, error: msg };
  }
  // DEZELFDE BOTSING, DERDE DEUR — en deze loopt niet over `blankNode()` maar
  // over de PARSER. De N3-parser mint de anonieme `[ … ]`-knopen en de
  // lijstknopen uit precies dezelfde naamloze fabriek (N3Parser.js r.284, 404,
  // 463, 603, 679, 717 …), en `blankNodePrefix` raakt die niet: die optie geldt
  // alleen voor `_:label`-knopen uit het document. Deze parse draait op de
  // HOOFDDRAAD, waar de teller op nul staat, en zijn quads gaan de BESTAANDE
  // graaf in — dus een geplakt fragment met één `[ … ]` erin overschrijft een
  // anonieme knoop uit de worker-parse. Voor `loadSources` geldt dat niet: daar
  // gaat de parse in een verse store, en dan botst hij alleen met zichzelf.
  //
  // Elke blanke knoop uit dit fragment is per definitie een NIEUWE knoop (de
  // oude sluiting wordt hieronder juist weggehaald), dus hernoemen kost niets
  // en houdt de interne structuur van het fragment intact: dezelfde bron-label
  // krijgt dezelfde verse knoop.
  const vers = new Map();
  const her = (x) => {
    if (x.termType !== 'BlankNode') return x;
    if (!vers.has(x.value)) vers.set(x.value, mintBlank(store));
    return vers.get(x.value);
  };
  // Ook de GRAAFNAAM: de parser accepteert TriG, dus een geplakt `_:g { … }`
  // levert een blanke graafnaam op die zonder hernoeming met een bestaande
  // graafnaam kan samenvallen — dezelfde botsing, vierde positie (punt 16).
  quads = quads.map((q) => (q.subject.termType === 'BlankNode'
    || q.object.termType === 'BlankNode' || q.graph.termType === 'BlankNode'
    ? N3.DataFactory.quad(her(q.subject), q.predicate, her(q.object), her(q.graph)) : q));

  const old = closureQuads(store, t);
  const containsSubject = t.termType !== 'NamedNode'
    || quads.some((q) => q.subject.termType === 'NamedNode' && q.subject.value === t.value);
  store.removeQuads(old);
  store.addQuads(quads);
  return { ok: true, removed: old.length, added: quads.length, containsSubject };
}

// --- Export -----------------------------------------------------------------

// De export is Turtle/JSON-LD, dus zonder graphs: elke bron staat sinds de
// bronnenlaag in zijn eigen named graph, en een writer die dat ziet schrijft
// TriG (`<graph> { … }`). dedupeTriples strípt de graph én ontdubbelt de
// triples die in meer dan één bron staan.
export function exportTurtle(store, { graph = null } = {}) {
  const writer = new N3.Writer({ prefixes: allPrefixes() });
  const quads = graph
    ? store.getQuads(null, null, null, namedNode(graph))
    : store.getQuads(null, null, null, null);
  writer.addQuads(dedupeTriples(quads));
  let out = '';
  writer.end((err, result) => { if (!err) out = result; });
  return prunePrefixes(out);
}

// Eén named graph als losse store, met de graph eraf. exportJsonLd loopt de
// graaf via store.getQuads(subject, …) af — ook diep, voor geneste blank nodes
// en gevolgde bouwstenen — en dat pad filtert niet op graph. Zonder deze kopie
// zou de JSON-LD-download van ÉÉN bron de triples van alle bronnen meenemen.
function graphStore(store, graph) {
  const uit = new Store();
  uit.addQuads(dedupeTriples(store.getQuads(null, null, null, namedNode(graph))));
  return uit;
}

// `graph`: dezelfde per-bron-filtering als exportTurtle (de downloadknoppen in
// het bronnenpaneel geven allebei precies die ene bron mee).
export function exportJsonLd(store, { graph = null } = {}) {
  if (graph) store = graphStore(store, graph);
  const all = store.getQuads(null, null, null, null);
  const asObject = new Set(all.filter((q) => q.object.termType === 'BlankNode')
    .map((q) => q.object.value));
  const tops = new Map();
  for (const q of all) {
    if (q.subject.termType === 'BlankNode' && asObject.has(q.subject.value)) continue;
    const key = q.subject.termType + ':' + q.subject.value;
    if (!tops.has(key)) tops.set(key, q.subject);
  }
  const bodies = [...tops.values()].map((s) => subjectJsonLdBody(store, s));
  return JSON.stringify({ '@context': jsonLdContext(bodies), '@graph': bodies }, null, 2);
}

// --- Verplaatsen en hergebruiken (taak 8) -----------------------------------
//
// De sleep-mutaties. Twee bewust verschillende beloften:
//   moveAttached — de KOPPEL-triple verhuist, de knoop zelf blijft precies
//                  waar hij stond (geen kopie, geen verse blank nodes);
//   linkAttached — er komt alleen een koppeling BIJ: één knoop in twee Sets.
// Beide zijn zo dom mogelijk gehouden: geen sluitingslogica, geen dubbele
// boekhouding. removeAttached (structuurbewerkingen hierboven) ruimt een
// wees op als niemand meer verwijst; moveAttached/linkAttached doen daar
// bewust NIETS mee — de knoop blijft altijd bereikbaar vanaf minstens de
// nieuwe (of, bij linkAttached, de oude ÉN de nieuwe) plek, dus er ontstaat
// nooit een wees om op te ruimen.

// Sleutel om twee termen te vergelijken zonder RDF/JS-term-identiteit nodig
// te hebben (twee blank-node-objecten met dezelfde `.value` uit dezelfde
// store zijn dezelfde knoop, ook als het niet hetzelfde JS-object is).
//
// Hij stond hier met een EIGEN id-tabel — de tweede van de elf decodeerplekken,
// en zij liep op twee ingangen uit de pas met de eerste. Sinds de consolidatie
// is hij afgeleid van `termVan`; de tabel staat in `model/term.js` en de pin
// erop in `model/test/term.test.mjs`. De doorgifte blijft, want de sleepkant
// (`slepen/sleepgebaar.ts`) haalt hem samen met de mutaties uit dit bestand.
export { termSleutel };

// STAAT `kandidaat` IN DE SLUITING VAN `root` (of is hij `root` zelf)? De
// bewaking tegen een cykel: een knoop onder zijn eigen nakomeling hangen zou
// een lus maken die geen enkele lezer (of schrijver) meer normaal doorloopt.
// closureQuads volgt alleen blank nodes (zie boven) — dat is exact de
// sluiting die ook duplicatePolicy/policyWisQuads als "van deze knoop"
// beschouwen, dus dezelfde grens hier.
function inEigenSluiting(store, root, kandidaat) {
  const kS = termSleutel(kandidaat);
  if (termSleutel(root) === kS) return true;
  for (const q of closureQuads(store, root)) {
    if (termSleutel(q.object) === kS) return true;
  }
  return false;
}

// Verplaats de koppeling (fromParent, fromPred, term) naar (toParent, toPred,
// term): de knoop zelf wordt niet aangeraakt, alleen de ÉÉN triple die hem
// aanhecht. Drie weigeringen:
//  - geen bestaande koppeling: geen stille kopie van iets dat er niet is;
//  - dezelfde plek: een no-op, expliciet vóór elke mutatie afgevangen zodat
//    er geen delta (en dus geen undo-stap) ontstaat voor niets;
//  - een cykel (de knoop onder zichzelf of een eigen nakomeling hangen).
export function moveAttached(store, fromParent, fromPred, term, toParent, toPred) {
  const fp = nn(fromParent);
  const tp = nn(toParent);
  const t0 = nn(term);
  const fPred = typeof fromPred === 'string' ? fromPred : fromPred.value;
  const tPred = typeof toPred === 'string' ? toPred : toPred.value;
  const existing = store.getQuads(fp, namedNode(fPred), t0, null);
  if (!existing.length) {
    throw new Error('moveAttached: geen bestaande koppeling om te verplaatsen');
  }
  const zelfdePlek = fp.termType === tp.termType && fp.value === tp.value && fPred === tPred;
  if (zelfdePlek) return;
  if (inEigenSluiting(store, t0, tp)) {
    throw new Error('moveAttached: een knoop kan niet in zijn eigen sluiting hangen (cykel)');
  }
  store.removeQuads(existing);
  store.addQuad(tp, namedNode(tPred), t0);
}

// Alleen een koppeling TOEVOEGEN — de bestaande blijft staan. "Eén knoop in
// twee Sets": hergebruik, geen verhuizing.
export function linkAttached(store, toParent, toPred, term) {
  const tPred = typeof toPred === 'string' ? toPred : toPred.value;
  store.addQuad(nn(toParent), namedNode(tPred), nn(term));
}

// WAAR HANGT EEN VOORWAARDE (of refinement) AAN? {parent, pred} met
// pred: 'constraint' | 'refinement'. Bij 'constraint' is `parent` zelf de
// aanhechtknoop (rule of duty — beide zijn in ODRL een Rule). Bij
// 'refinement' is `parent` de RULE/DUTY, en wordt de action-knoop
// opgezocht (of aangemaakt): ensureActionNode wikkelt een kale actie-IRI
// eerst in een blank node met rdf:value, zoals de bestaande datastructuur in
// de voorbeelden dat al doet voor doelbindingen (zie setPurpose hierboven).
function verplaatsHouder(store, spec) {
  const p = nn(spec.parent);
  if (spec.pred === 'refinement') {
    return { houder: ensureActionNode(store, p), predIri: ODRL + 'refinement' };
  }
  return { houder: p, predIri: ODRL + 'constraint' };
}

// Verplaats (of, met `{ kopie: true }`, kopieer/hergebruik) een voorwaarde
// tussen twee aanhechtpunten — typisch rule-odrl:constraint <-> de
// odrl:refinement van de action-knoop van dezelfde of een andere regel.
// Bouwt voort op moveAttached/linkAttached: geen eigen mutatielogica, alleen
// de vertaling van het logische {parent, pred} naar de echte aanhechtknoop.
//
// verplaatsHouder MUTEERT bij pred:'refinement' (ensureActionNode wikkelt een
// kale actie-IRI om). Daarom wordt hij voor de BRON pas opgevraagd als er ook
// werkelijk iets van de bron losgemaakt gaat worden: bij een kopie blijft de
// bron onaangeroerd, en een herwikkeling die niemand vroeg zou daar een
// mutatie zijn — op een alleen-lezen bron zelfs een verboden schrijfactie.
export function verplaatsConstraint(store, from, cTerm, to, opts = {}) {
  const t0 = nn(cTerm);
  const doel = verplaatsHouder(store, to);
  if (opts.kopie) {
    linkAttached(store, doel.houder, doel.predIri, t0);
    return;
  }
  const bron = verplaatsHouder(store, from);
  moveAttached(store, bron.houder, bron.predIri, t0, doel.houder, doel.predIri);
}

// --- Geldige drop-doelen (taak 8, DOM-vrij) ----------------------------------
//
// Twee soorten sleepitems:
//  - 'knoop': een regel/verbod (pred odrl:permission|prohibition) mag alleen
//    naar KAARTKOPPEN met datzelfde predicaat; een plicht (elk ander
//    predicaat — odrl:obligation/duty/consequence) mag naar kaartkoppen (als
//    odrl:obligation) ÉN naar regel-rijen (als odrl:duty).
//  - 'voorwaarde': mag naar de odrl:constraint van elke REGEL-ACHTIGE knoop
//    (toestemming, verbod én plicht — alle drie zijn in ODRL een Rule met een
//    eigen constraint en action), of naar de odrl:refinement-zone van diens
//    actie-knoop — nooit naar een kaart.
//
// `item`: { soort, term, ouder, pred }. `opts.mag(term, soort, pred)`: het
// BEWERKBAARHEIDSFILTER van de aanroeper. Die drie argumenten zijn er omdat
// niet elk doel dezelfde toets vraagt: bij 'kaart'/'regel' komt er alleen een
// koppeling BIJ (de losse toets "leeft de knoop in een schrijfbron"), terwijl
// een 'actie'-doel de bestaande odrl:action kan moeten herwikkelen en dus de
// veld-fijne toets op dát triple vraagt. Zonder de soort zou de aanroeper zijn
// eigen kandidatenlijst moeten nabouwen — precies de parallelle logica die
// deze functie moet voorkomen. Zonder `mag` komt alles door wat STRUCTUREEL
// geldig is.
//
// Nooit de plek waar het item al hangt (zelfde ouder + predicaat), nooit het
// item zelf, en — omdat de kandidatenlijsten hieronder uitsluitend uit POLICIES
// en RULES bestaan, nooit uit de knoop zelf of zijn eigen
// (blank-node-)nakomelingen — is een cykel structureel uitgesloten.
// DE SOORT-NAMEN ZIJN EEN CONTRACT tussen deze pure functie en de UI: doc.js
// meldt zijn drop-zones met dezelfde drie namen aan (dropDoelNode) en kiest er
// zijn bewerkbaarheidstoets mee (dropDoelBewerkbaar). Als losse tekenreeksen
// aan twee kanten zou een tikfout zich uiten als "dit doel licht nooit op" —
// stil, en pas in de browser zichtbaar. Dus één plek.
export const SLEEPITEM = { KNOOP: 'knoop', VOORWAARDE: 'voorwaarde' };
export const DROPDOEL = { KAART: 'kaart', REGEL: 'regel', ACTIE: 'actie' };

const RULE_PREDS = new Set([ODRL + 'permission', ODRL + 'prohibition']);

function allePolicies(model) {
  return [...(model.sets || []), ...(model.offers || []), ...(model.agreements || [])];
}
function alleRegels(model) {
  const out = [];
  for (const p of allePolicies(model)) {
    for (const r of (p.permissions || [])) out.push(r);
    for (const r of (p.prohibitions || [])) out.push(r);
  }
  return out;
}

// ALLE RULES IN DE ODRL-ZIN: toestemmingen, verboden ÉN plichten. Een Duty is
// in ODRL net zo goed een Rule — zij draagt haar eigen odrl:constraint en haar
// eigen odrl:action, en dus ook een eigen refinement-zone. Alleen de
// VOORWAARDE-tak gebruikt deze lijst; de knoop-tak houdt het bij alleRegels(),
// want een plicht ONDER een plicht is odrl:consequence en dat is een andere
// bewerking dan deze sleep.
//
// Zonder de plichten erbij zou de sleepgreep op de voorwaarde van een plicht
// een eenrichtingsdeur zijn: eraf slepen kan, terugslepen nooit.
function alleRegelachtigen(model) {
  const out = [];
  const gezien = new Set();
  const voegToe = (r) => {
    if (!r || !r.term || gezien.has(termSleutel(r.term))) return;
    gezien.add(termSleutel(r.term));
    out.push(r);
    for (const d of (r.duties || [])) voegToe(d);
    for (const d of (r.obligations || [])) voegToe(d);
  };
  for (const p of allePolicies(model)) {
    for (const r of (p.permissions || [])) voegToe(r);
    for (const r of (p.prohibitions || [])) voegToe(r);
    for (const d of (p.obligations || [])) voegToe(d);
  }
  return out;
}

export function geldigeDropDoelen(model, item, opts = {}) {
  if (!model || !item || !item.term) return [];
  const mag = typeof opts.mag === 'function' ? opts.mag : () => true;
  const zelfdePlek = (term, pred) => item.ouder
    && termSleutel(term) === termSleutel(item.ouder) && pred === item.pred;
  const uit = [];
  const voeg = (soort, term, pred) => {
    if (zelfdePlek(term, pred)) return;
    if (termSleutel(term) === termSleutel(item.term)) return;
    if (!mag(term, soort, pred)) return;
    uit.push({ soort, term, pred });
  };
  if (item.soort === SLEEPITEM.VOORWAARDE) {
    for (const r of alleRegelachtigen(model)) {
      voeg(DROPDOEL.REGEL, r.term, 'constraint');
      voeg(DROPDOEL.ACTIE, r.term, 'refinement');
    }
    return uit;
  }
  if (RULE_PREDS.has(item.pred)) {
    for (const p of allePolicies(model)) voeg(DROPDOEL.KAART, p.term, item.pred);
    return uit;
  }
  // Plicht-achtig (obligation/duty/consequence): naar kaarten als
  // odrl:obligation, naar regels als odrl:duty.
  for (const p of allePolicies(model)) voeg(DROPDOEL.KAART, p.term, ODRL + 'obligation');
  for (const r of alleRegels(model)) voeg(DROPDOEL.REGEL, r.term, ODRL + 'duty');
  return uit;
}

// --- Dropdown-vulling -------------------------------------------------------

const KNOWN_ACTIONS = ['use', 'read', 'distribute', 'reproduce', 'modify', 'delete', 'inform']
  .map((l) => ODRL + l);
const KNOWN_OPERATORS = ['eq', 'neq', 'gt', 'gteq', 'lt', 'lteq', 'isA', 'hasPart', 'isPartOf', 'isAllOf', 'isAnyOf']
  .map((l) => ODRL + l).concat([APNL + 'conformsToPolicy']);
const KNOWN_LEFT_OPERANDS = [ODRL + 'purpose', ODRL + 'dateTime', ODRL + 'count', APNL + 'verwerkingsverzoek'];

/** DE REGISTERBASES WAARONDER EEN GELABELDE KNOOP EEN ORGANISATIE IS.
 *
 *  EIGENAARSRICHTING 9 SEP 2026: "We moeten ook gaan kijken hoe we bestaande
 *  named nodes kunnen gaan hergebruiken; bij Aanbieder/Afnemer bijvoorbeeld."
 *  De viewer laadt `data/labels-tooi.ttl` bij ELKE bron mee (VOCABULAIRE in
 *  `model/default-corpus.js`) juist zodat "gemeente Appingedam" te lezen valt in
 *  plaats van "gem:gm0003". Die knopen stonden tot nu toe alleen in `labeled` —
 *  de VRIJE suggestielijst die geen enkel partijveld gebruikt — en waren dus
 *  wel te LEZEN en niet te KIEZEN. Een aanbieder overtypen uit een register dat
 *  al geladen is, is precies de dubbeling die de eigenaar noemt.
 *
 *  WAAROM EEN BASISLIJST EN GEEN TYPE-TOETS. Een registerfragment is met opzet
 *  minimaal: het draagt een label, een prefLabel en een dct:source, en géén
 *  rdf:type — het register zelf is de bron van dat gegeven, niet het fragment.
 *  Er is dus geen type om op te toetsen; wat een TOOI-identifier tot organisatie
 *  maakt is zijn PLEK in de identifier-ruimte. Deze lijst is dan ook DATA in de
 *  vorm van een constante, net als `DEFAULT_REGISTER_PREFIXES`: een uitrol met
 *  een ander organisatieregister zet zijn eigen basis erbij.
 *
 *  Een knoop onder deze basis moet nog steeds een LABEL dragen: zonder label is
 *  er niets te tonen dan de kale IRI, en dan is de suggestie geen hulp. */
export const REGISTER_PARTIJ_BASES = ['https://identifier.overheid.nl/tooi/id/'];

/** WELK TYPE MAAKT EEN KNOOP KANDIDAAT VOOR WELKE VELDSOORT.
 *
 *  De tweede bron naast "wordt in die rol al gebruikt". Een `odrl:Party` die nog
 *  nergens aanbieder is, een `dcat:Dataset` die nog aan geen enkele regel hangt
 *  en een `dpv:Purpose` uit de doelenlijst zijn precies de knopen die je wilt
 *  KUNNEN kiezen — zonder deze tak verschijnen ze pas in de suggesties nádat
 *  iemand ze een keer met de hand heeft ingetypt.
 *
 *  `dpv:Purpose` is de doelklasse van het profiel (odrl-ap-nl.ttl §5: "de
 *  rightOperand van een odrl:purpose-refinement verwijst naar een
 *  verwerkingsdoel (dpv:Purpose)"); ODRL zelf kent geen doelklasse. */
const TYPE_KANDIDAAT = [
  [ODRL + 'Action', 'actions'], [ODRL + 'Operator', 'operators'],
  [ODRL + 'LeftOperand', 'leftOperands'],
  [ODRL + 'Party', 'parties'], [ODRL + 'PartyCollection', 'parties'],
  [FOAF + 'Organization', 'parties'], [FOAF + 'Agent', 'parties'],
  [ODRL + 'Asset', 'targets'], [ODRL + 'AssetCollection', 'targets'],
  [DCAT + 'Dataset', 'targets'], [DCAT + 'Distribution', 'targets'],
  [DPV + 'Purpose', 'purposes'],
];

// Opties per rol: bekende odrl/apnl-termen, termen die in de graaf in die rol
// gebruikt worden, en (apart) alles met een rdfs:label als vrije suggestielijst.
export function termOptions(store) {
  const mk = () => new Map();
  const add = (map, iri) => {
    if (!iri || map.has(iri)) return;
    map.set(iri, { iri, curie: curie(iri), label: labelFor(store, namedNode(iri)) });
  };
  const actions = mk(); const operators = mk(); const leftOperands = mk();
  const parties = mk(); const targets = mk(); const purposes = mk(); const labeled = mk();

  KNOWN_ACTIONS.forEach((i) => add(actions, i));
  KNOWN_OPERATORS.forEach((i) => add(operators, i));
  KNOWN_LEFT_OPERANDS.forEach((i) => add(leftOperands, i));

  const perNaam = {
    actions, operators, leftOperands, parties, targets, purposes, labeled,
  };
  for (const [ty, naam] of TYPE_KANDIDAAT) {
    for (const q of store.getQuads(null, namedNode(RDF + 'type'), namedNode(ty), null)) {
      if (q.subject.termType === 'NamedNode') add(perNaam[naam], q.subject.value);
    }
  }
  const usedIn = [
    [ODRL + 'operator', operators], [ODRL + 'leftOperand', leftOperands],
    [ODRL + 'action', actions], [RDF + 'value', actions],
    [ODRL + 'assigner', parties], [ODRL + 'assignee', parties],
    [DCT + 'publisher', parties], [ODRL + 'informedParty', parties],
  ];
  for (const [pred, map] of usedIn) {
    for (const q of store.getQuads(null, namedNode(pred), null, null)) {
      if (q.object.termType === 'NamedNode') add(map, q.object.value);
    }
  }
  for (const pred of targetPreds(store)) {
    for (const q of store.getQuads(null, namedNode(pred), null, null)) {
      if (q.object.termType === 'NamedNode') add(targets, q.object.value);
    }
  }
  // Purposes: rightOperand van constraints met leftOperand odrl:purpose.
  for (const q of store.getQuads(null, namedNode(ODRL + 'leftOperand'), namedNode(ODRL + 'purpose'), null)) {
    const right = objOf(store, q.subject, ODRL + 'rightOperand');
    if (right && right.termType === 'NamedNode') add(purposes, right.value);
  }
  // Alles met een rdfs:label (voor het vrije IRI-veld / datalist), en daarbinnen
  // de REGISTER-ORGANISATIES als partijkandidaat — zie `REGISTER_PARTIJ_BASES`.
  for (const q of store.getQuads(null, namedNode(RDFS + 'label'), null, null)) {
    if (q.subject.termType !== 'NamedNode') continue;
    add(labeled, q.subject.value);
    if (REGISTER_PARTIJ_BASES.some((b) => q.subject.value.startsWith(b))) {
      add(parties, q.subject.value);
    }
  }
  const sort = (map) => [...map.values()].sort((a, b) => a.label.localeCompare(b.label, 'nl'));
  return {
    actions: sort(actions), operators: sort(operators), leftOperands: sort(leftOperands),
    parties: sort(parties), targets: sort(targets), purposes: sort(purposes), labeled: sort(labeled),
  };
}

// Lege store (voor "Nieuw beleid" zonder geladen bronnen).
export function newStore() {
  return new Store();
}
